(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["audio"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-vida-man-visual-dialog-with-digital-2021"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-1\">一 · 场景：一次打断之后，谁在拖首包</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-2\">二 · 旧栈的主流做法：整段生成、整段合成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-3\">三 · 自回归逐帧生成为什么天然拖首包</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-4\">四 · 视觉特征与对话历史的显存账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-5\">五 · 批调度与实时率：静态批在对话负载下的失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-6\">六 · 为什么这套旧栈在 Blackwell 上仍然值得改</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-7\">七 · 请求形态：四段流水上的长度分布与并发结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-8\">八 · SLO 的分解口径：首包、实时率与音画同步三个独立指标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-9\">九 · 长尾：会话深度、视觉特征与首块阻塞</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-10\">十 · 负载塑造方案：块长、缓存与批边界的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-11\">十一 · 可核查的测量口径清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-12\">十二 · 工程判断：把块长当作一等部署参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-13\">十三 · 首块声学表征的 kernel 形态与精度选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-14\">十四 · 累加精度与误差如何在流式链路里累积</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-15\">十五 · tcgen05 与 TMEM：把首块 kernel 的同步开销压下去</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-16\">十六 · 2-SM MMA：用配对 SM 换首块吞吐还是换尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-17\">十七 · 第五代 Tensor Core 的精度-吞吐曲线与声码器侧</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-18\">十八 · 把公式落到一次首包前向的伪代码思路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-19\">十九 · 首块优先的边界：流式切块、声码器阻塞与增量缓存的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-20\">二十 · 显存账本的四个抽屉与可复算基线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-21\">二十一 · 历史与视觉特征的 KV 账本：增量维护不等于不增长</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-22\">二十二 · 分页与复用：PagedAttention 在流式场景的变体</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-23\">二十三 · 卸载与压缩：把冷历史赶出 HBM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-24\">二十四 · HBM3e 容量怎么算：一个可复算的预算表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-25\">二十五 · 带宽瓶颈的落点与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-26\">二十六 · 流式语音合成下的显存账本与首包边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-27\">二十七 · 四段流水上的调度对象与代价函数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-28\">二十八 · 连续批处理：按块而非按请求做调度单位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-29\">二十九 · Chunked prefill：把长上下文切开喂给首块</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-30\">三十 · 优先级与抢占：谁让路、让多少</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-31\">三十一 · 分离式预填/解码与声码器的带宽账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-32\">三十二 · 时延与吞吐的取舍落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-33\">三十三 · 从四段流水反推切分边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-34\">三十四 · NVLink 5 与 NVSwitch：域内带宽决定 TP 上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-35\">三十五 · All-to-All 与 EP：MoE 声学骨干的隐性代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-36\">三十六 · NIXL 传输：分离式预填/解码的数据面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-37\">三十七 · 通信何时成为瓶颈：三个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-38\">三十八 · 切分边界与通信瓶颈：ViDA-MAN 四段流水在并行拓扑上的失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-39\">三十九 · 精度塌陷：从“能出声”到“出怪声”的静默滑落</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-40\">四十 · OOM 与缓存膨胀：历史与视觉特征的隐性账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-41\">四十一 · 批抖动与尾延迟：连续批处理在流式音频下的错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-42\">四十二 · 静默降级：音画不同步与“看起来正常”的故障</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-43\">四十三 · 监控、定位与回滚：把四段流水做成可归因的链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-44\">四十四 · 首块阻塞与缓存膨胀：这套流式链路的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-45\">四十五 · 口径先行：这张卡能测什么、不能测什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-46\">四十六 · 硬件档位与 batch：机制上能推的代价边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-47\">四十七 · 指标怎么读：TTFT/TPOT 在语音链路上的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-48\">四十八 · 哪些提升不可比：跨系统对比的方法边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-49\">四十九 · 补测设计：把这张卡变成可核验的基准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-50\">五十 · 落到工程判断：口径即容量规划的前置条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-51\">五十一 · 迁移到非流式模型：首块优先的前提会失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-52\">五十二 · 视觉特征缓存：增量维护的边界在特征维度与轮次深度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-53\">五十三 · 声码器与音画同步：迁移到高帧率驱动时节奏会错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-54\">五十四 · 规模上限：四段流水串联，最慢段决定并发天花板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-55\">五十五 · 不适用的场景与判断清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-vida-man-visual-dialog-with-digital-2021-sec-56\">五十六 · 迁移的代价不在算子，在流式契约的重新谈判</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:551px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 551.0 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用户语音进入前端，识别为文本并与当前视频帧特征一起送入对话管理器。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对话管理器按轮次拼接历史，生成回复文本并切分为语义块。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">声学生成器以流式方式逐块产生声学表征，首块优先返回以压低首包延迟。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">声码器把声学表征转成波形，同时驱动数字人口型与表情同步。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">波形按块推流给客户端，后续块在生成同时持续补齐。</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">一轮结束后历史与视觉特征增量更新，进入下一轮对话。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-1\">一 · 场景：一次打断之后，谁在拖首包</h3>\n<p>设想一个已上线的数字人客服：用户对着屏幕说话，摄像头同时采集用户画面。用户说到一半改口，前端语音识别必须尽快给出稳定文本；对话管理器要把这一轮的文本、前几轮历史与当前视频帧特征拼成多模态输入，生成回复文本；回复文本按语义切块进入声学生成器，首块声学表征一出来就交给声码器转波形，数字人开口、口型与表情随之启动。用户感知的“响应快不快”，不是整段回复多快生成完，而是从用户说完到数字人发出第一个音节之间的那段空白。这段空白就是首包延迟，它由四段串行耗时相加：</p>\n<div class=\"formula\">$$ T_{\\mathrm{first}} = T_{\\mathrm{asr}} + T_{\\mathrm{dialog}} + T_{\\mathrm{acoustic}}^{\\mathrm{first\\ block}} + T_{\\mathrm{vocoder}}^{\\mathrm{first\\ chunk}} $$</div>\n<p>这个式子的工程含义很直接：四项是加法关系，没有一项可以被其他项的并行掩盖。识别慢一点、对话管理器多算一轮历史、声学生成器等首块凑满、声码器等整句表征到齐，任何一处阻塞都原样加到用户等待上。数字人场景比纯语音助手更苛刻的地方在于，音画同步把声码器的输出节奏和口型驱动绑在一起——首包不只是“有声音”，还要“有对的嘴型”，声码器首块延迟因此无法用预生成或缓存波形绕过去。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-2\">二 · 旧栈的主流做法：整段生成、整段合成</h3>\n<p>在这类系统进入流式组织之前，推理栈的默认形态是“请求—整段—返回”。语音合成侧典型链路是：回复文本一次性送入声学模型，自回归逐帧或逐 token 生成完整声学表征序列，序列全部就绪后一次性交给声码器，声码器再整段上采样成波形，最后把整段音频推给客户端。这条链路在离线批处理里很自然，因为批内所有请求都按同一节奏推进，GPU 利用率高、实现简单、数值路径短。但放到多轮视觉对话的在线服务里，它把首包延迟变成了整段生成时间：声学模型自回归逐帧生成会线性拉长首包时间，回复越长，用户等得越久，而用户在第一秒就已经在判断这个数字人“是不是卡住了”。</p>\n<p>更麻烦的是多轮带来的状态膨胀。旧做法每轮都把完整对话历史与视觉特征重新编码一遍，历史越长、视频帧特征越多，对话管理器的前向计算与显存占用越随轮次增长。视觉特征尤其昂贵：每帧画面经视觉编码器得到的特征张量要保留在显存里供多模态拼接使用，多路并发会话叠加后，这部分缓存会挤占本已紧张的 KV cache 与激活空间。批调度层面，旧栈通常按“整段请求”做静态批：一个批里最长的回复决定整批的完成时间，短回复被长回复拖住，实时率（生成的音频时长与墙钟时间之比）在长短混合的负载下明显下滑。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>旧栈形态</th><th>直接代价</th></tr></thead><tbody><tr><td>声学生成</td><td>整段自回归，全部帧生成完才交付</td><td>首包延迟随回复长度线性增长</td></tr><tr><td>声码器</td><td>等整段表征到齐再上采样</td><td>首包再叠加一次整段合成时间</td></tr><tr><td>对话状态</td><td>每轮重编码全量历史与视觉特征</td><td>显存随轮次增长，前向算力重复消耗</td></tr><tr><td>批调度</td><td>静态批，按最长请求对齐</td><td>短请求被拖尾，实时率与并发下降</td></tr></tbody></table>\n<p>这套形态在纯文本对话里尚可容忍，因为文本可以逐 token 流式吐给前端，用户看到字在动就有反馈。语音不行：波形必须由声码器产出，而声码器在旧栈里被放在整段表征之后，前端拿不到任何中间产物。这就是“非改不可”的根源——不是某个算子慢，而是流水线的组织方式把可并行的部分串行化了，把可增量的状态全量重算了。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-3\">三 · 自回归逐帧生成为什么天然拖首包</h3>\n<p>声学模型的自回归结构决定了第 n 帧依赖前 n−1 帧，生成过程无法在时间上跳跃。若总帧数为 N、单帧前向耗时为 t，则整段声学生成时间近似为 N·t，首包必须等到第 N 帧之后才能交付给声码器。即便把声码器改成流式，只要声学侧仍按“整段”交付，首包延迟的下界就被 N·t 锁死。ViDA-MAN 的改法是把这条依赖切成块：首块只生成少量帧就立即交付，后续块在首块已被声码器消费的同时继续推进。首包延迟于是从 N·t 降到 n₀·t（n₀ 为首块帧数），而总生成时间基本不变——这是典型的用流水线重叠换首包，不减少总计算量，只改变交付顺序。</p>\n<p>代价转移到了别处。切块意味着声学模型要在块边界处维护自回归状态（隐状态、注意力缓存），块与块之间不能重新初始化，否则音质在拼接处断裂；声码器则要在首块上做“冷启动”上采样，首块的感受野不完整，边界处理不当会产生爆音或口型跳变。工程上还要处理块长与实时率的匹配：块太短，首包快但块边界多、状态维护开销与声码器调用次数上升；块太长，首包被拉长。论文材料没有给出具体切块阈值，因此这里只能把判断落在机制上——首块长度是首包延迟与音质稳定性的直接权衡旋钮，必须按 SLO 反推，而不能当作固定常数引用。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-4\">四 · 视觉特征与对话历史的显存账</h3>\n<p>数字人视觉对话的另一条旧栈痛点不在时间而在空间。多模态对话管理器每轮需要把当前视频帧特征与历史文本拼成输入，旧做法每轮重编码全量历史，等价于把 O(轮次) 的算力重复支付，同时把视觉特征张量常驻显存。设单帧视觉特征为 F、历史轮数为 R、并发会话数为 C，则仅视觉特征缓存的显存量级为 C·R·F；对话历史的 KV 部分同理随 R 增长。在旧栈的静态批下，这部分显存与批内最长请求绑定，短会话也要按长会话的缓存上限预留，显存利用率被拉低。</p>\n<p>ViDA-MAN 的增量维护把这条曲线压平：历史与视觉特征按轮次追加，只对新进入的轮次做编码，旧轮次的表征直接复用。这省掉的是重复前向算力，但引入的是缓存管理问题——增量缓存的淘汰策略、跨轮次的一致性、视觉特征与文本历史的对齐方式，材料均未给出上限与规则。工程判断上，增量缓存把显存从“随轮次线性增长的重算缓冲”变成“随轮次线性增长的常驻状态”，前者可以用算力换空间，后者只能靠淘汰策略控制上限；在 Blackwell 档位上，这部分常驻状态会与 KV cache 争夺同一块 HBM，容量规划时必须把它和声学模型的激活、声码器的中间张量放在同一张账上算。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-5\">五 · 批调度与实时率：静态批在对话负载下的失效</h3>\n<p>在线数字人服务的请求分布是长短混合的：一句“嗯”与一段产品说明并存。旧栈的静态批按批内最长请求对齐完成时间，短请求的音频早已生成完却要等长请求，实时率被拖低；更严重的是首包——批内所有请求的首包都要等最慢那条路径，尾延迟直接变成全体用户的等待。连续批处理（continuous batching）的思路是把请求按步推进、完成即退出，但这要求生成侧本身是可分步的；整段自回归的声学模型在旧栈里没有“步”的概念，只有“整段”，因此批调度无法细化到块级别。</p>\n<p>ViDA-MAN 把声学生成与声码器拆成两段推进，实际上为块级调度创造了接口：首块可以作为独立的调度单元优先推进，后续块按实时率节拍补齐。代价是调度器要同时跟踪声学侧与声码器侧两条队列的进度，块边界处的状态交接必须无锁或低锁，否则调度开销会吃掉流水线收益。材料未给出并发数与实时率指标，因此这里不给出容量数字，只指出机制上的约束：首包优先意味着调度器必须能给首块插队，而这会牺牲一部分批内吞吐的整齐度——首包延迟与吞吐在块级调度下是一对需要显式定价的指标。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-6\">六 · 为什么这套旧栈在 Blackwell 上仍然值得改</h3>\n<p>把问题放到 SM100/SM103 的语境里，旧栈的浪费更具体：整段自回归生成把 tcgen05 MMA 与 TMEM 的吞吐优势压在长序列的串行依赖上，矩阵单元的利用率被自回归的逐帧节奏限制；整段声码器上采样是一次性的大激活峰值，显存带宽在首包窗口内被空转等待；静态批让 SM 在长短混合负载下出现大量空闲周期。ViDA-MAN 的流式切块并不直接解决这些硬件层面的利用率问题，但它改变了交付顺序，使得首块可以尽早占用计算资源、后续块与声码器重叠，从而把“等待整段”的空转窗口填上。对部署者而言，这意味着容量规划不能只按平均吞吐算，而要把首包延迟作为一等指标：在同样的 HBM 与功耗预算下，流式组织允许更小的首块、更细的调度粒度，代价是状态维护与块边界处理的工程复杂度。</p>\n<p>落到具体机制上，第一处要改的是声学生成器的交付契约：从“返回整段表征”改为“返回首块表征并保持可续生成的状态”，这要求自回归缓存跨块存活、块边界处不重置隐状态；第二处是声码器的调用契约：从“整段输入”改为“首块冷启动 + 后续块流式拼接”，边界窗与重叠长度必须显式定义；第三处是对话管理器的缓存契约：从“每轮全量重编码”改为“按轮次增量追加 + 显式淘汰上限”。这三处契约共同决定了 \\(T_{\\mathrm{first}}\\) 四项中后两项的可压缩空间，也决定了显存账上常驻状态与激活峰值如何分摊。论文材料只给出机制描述而未给出硬件、量化与实测数字，因此任何容量结论都必须以这三处契约的实测值为锚，而不能从架构参数反推。</p>\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-7\">七 · 请求形态：四段流水上的长度分布与并发结构</h3>\n<p>ViDA-MAN 的一次请求不是单条文本到语音的映射，而是一条四段串联的流水：语音前端识别、对话管理器理解与回复生成、声学生成器逐块产出表征、声码器转波形并驱动口型表情。负载形态的第一层刻画必须落在每段的输入长度上，而不是笼统的“请求数”。识别段的输入是用户语音流的时长；对话段的输入是识别文本加上当前视频帧特征，并按轮次拼接历史；声学生成段的输入是回复文本切出的语义块序列；声码器段的输入是声学表征块。四段长度量纲不同（秒、token、帧、块），任何把“平均请求长度”压成单一数字的做法都会掩盖瓶颈所在。</p>\n<p>并发结构同样不是平面的。多轮视觉对话中，一个会话在时间上是串行的：第 n 轮的回复必须先于第 n+1 轮的用户语音被消费，否则历史与视觉特征增量维护的语义就断了。因此系统面对的是“会话内串行、会话间并行”的两层并发。可核查的口径是：并发会话数 N<sub>s</sub>、每会话轮次深度 D、每轮回复的语义块数 B，以及每块对应的声学帧数 F。批大小只能在这四个维度上取，而不能把不同会话的不同轮次随意拼进同一批——拼批会破坏增量缓存的轮次边界。</p>\n<p>把首包延迟写成四段之和是本系统的核心约束：</p>\n<div class=\"formula\">$$ T_{\\mathrm{first}} = T_{\\mathrm{asr}} + T_{\\mathrm{dialog}} + T_{\\mathrm{acoustic}}^{\\mathrm{first\\ block}} + T_{\\mathrm{vocoder}}^{\\mathrm{first\\ chunk}} $$</div>\n<p>这个式子对负载形态有直接反作用：它要求首块尽可能短，而首块短意味着后续块数 B 增大，声码器调用次数与推流节奏的调度开销随之上升。于是“缩短首块”与“减少块数”构成一对张力，负载设计必须在这条张力线上取点。代价体现在延迟与吞吐的互换：首块越短，T<sub>first</sub> 越低，但单位回复的声码器启动次数越多，吞吐被调度开销侵蚀；首块越长则相反。工程上要测的不是单一首包延迟，而是首包延迟随首块长度变化的曲线。</p>\n<p>具体例子：一个会话第 3 轮，用户语音 4 秒，识别输出约数十个 token，回复文本被切成 5 个语义块，首块对应若干声学帧。若首块取回复的前一个短句，T<sub>acoustic</sub><sup>first block</sup> 被压到最小，但后续 4 块要在首块推流期间持续补齐；若首块取整段回复的前半，首包延迟抬升，后续块数降到 2，声码器启动次数减半。两种取法在端到端延迟与吞吐上的差异必须实测，材料未给出阈值，不能引用固定块长。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-8\">八 · SLO 的分解口径：首包、实时率与音画同步三个独立指标</h3>\n<p>数字人视觉对话的 SLO 不能只写一个端到端延迟。至少三个指标彼此独立且互相牵制：首包延迟 T<sub>first</sub>（用户说完到数字人开口）、流式实时率（后续块生成速度是否跟得上播放速度）、音画同步误差（口型与表情相对波形的偏移）。三者对应不同的失败模式：首包超标是“开口太慢”，实时率不足是“说到一半卡住”，同步误差是“嘴型对不上声音”。可核查的测量口径必须把三者分开采集，而不是用一个平均延迟掩盖。</p>\n<p>实时率的判据是后续块的产出速率不低于播放消费速率。设每块声学表征对应播放时长 τ<sub>play</sub>，块生成加合成的耗时为 τ<sub>gen</sub>，则稳态可播的条件是 τ<sub>gen</sub> ≤ τ<sub>play</sub>。这条不等式把负载形态与方案绑定：块越短，τ<sub>play</sub> 越小，对 τ<sub>gen</sub> 的要求越苛刻，实时率越难维持；块越长则实时率宽松但首包变差。首包与实时率因此不是两个可以独立优化的目标，而是同一条块长轴上的两端。</p>\n<p>音画同步的口径落在推流节奏上：声码器输出波形驱动口型与表情，首块与后续块的推流间隔若抖动，同步误差就累积。可测的量是相邻块推流时间戳的抖动分布，而不是单次误差。代价上，同步误差的容忍度决定了推流缓冲的深度：缓冲越深越平滑，但把首包延迟整体后移，等于用 T<sub>first</sub> 换同步稳定性。</p>\n<p>具体例子：若首块取极短以压低 T<sub>first</sub>，τ<sub>play</sub> 随之变小，后续块必须在很短的窗口内完成生成与合成，实时率裕度被吃掉；一旦某块 τ<sub>gen</sub> 超过 τ<sub>play</sub>，播放端要么插入静音要么拉长当前块，两种处理都直接表现为音画不同步。材料未给出同步误差指标，部署侧只能把推流时间戳抖动作为可采集的替代量。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-9\">九 · 长尾：会话深度、视觉特征与首块阻塞</h3>\n<p>长尾在这个系统里有三个来源，且都不是请求长度的简单尾部。第一是会话深度 D 的长尾：多轮对话中历史按轮次增量维护，深度越大，对话管理器拼接的多模态输入越长，T<sub>dialog</sub> 随 D 增长。第二是视觉特征的长尾：当前视频帧特征随场景变化，特征维度与帧率决定缓存占用，材料未给出缓存上限与淘汰策略，深度会话叠加高帧率场景会让显存占用单调爬升。第三是首块阻塞的长尾：四段串联中任一环节的偶发慢请求都会把 T<sub>first</sub> 推到尾部，而首包是用户感知最强的指标。</p>\n<p>长尾对批调度的反作用是结构性的。会话内串行意味着一个慢的首块会阻塞该会话后续所有块，而会话间并行意味着这个阻塞不应拖累其他会话。可核查的口径是按会话统计首包延迟的分位数，而不是把所有请求混在一起算平均；混算会把“少数深度会话的慢首包”稀释掉，掩盖真正的尾部来源。代价上，为压长尾而预留的并发槽位会降低平均吞吐，这是容量规划里必须显式承认的取舍。</p>\n<p>具体例子：一个深度为 8 的会话，历史拼接后对话段输入显著长于首轮会话，T<sub>dialog</sub> 抬升；若此时视觉特征缓存未做淘汰，显存占用随轮次累积，批大小被迫下调，反过来又拉长其他会话的排队时间。这条链路的因果是“缓存膨胀→批大小下降→排队延迟上升→首包尾部变厚”，而不是单点故障。</p>\n<p>长尾的测量口径要落到可采集的量：每会话首包延迟的 p50/p90/p99、每轮对话段输入长度、视觉特征缓存占用随轮次的增长曲线、声码器单块耗时的尾部。材料未给出这些数值，只能定性判断首块过长与声码器阻塞是机制上最直接的风险点。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-10\">十 · 负载塑造方案：块长、缓存与批边界的联动</h3>\n<p>负载形态不是被动输入，它直接决定方案的可选空间。块长选择是第一层：首块长度决定 T<sub>first</sub> 的下界，后续块长决定实时率裕度与声码器调用频率。方案反过来限制负载：一旦块长固定，回复文本的语义切块就必须服从这个粒度，切块策略从“按语义”退化为“按语义且不短于块长下限”，长句被合并、短句被补齐，语义自然度让位于调度可行性。</p>\n<p>缓存策略是第二层。对话历史与视觉特征按轮次增量维护，避免整段重算，这是方案对负载的正向约束：它把 T<sub>dialog</sub> 从随 D 线性增长压到随单轮增量增长。但增量维护要求缓存有上限与淘汰规则，否则显存占用随会话深度单调上升，批大小被动收缩。可核查的口径是缓存占用与会话深度的关系曲线，以及淘汰触发时的首包延迟跳变。材料未给出淘汰策略，这是部署侧必须自行补齐的空白。</p>\n<p>批边界是第三层。会话内串行、会话间并行意味着批只能在会话维度上拼，且同一会话的不同轮次不能同批。这把批大小的上界锁在并发会话数 N<sub>s</sub> 上，而不是请求队列长度。代价是：当 N<sub>s</sub> 小于硬件可承载的批容量时，吞吐被并发数而非算力限制；此时提升吞吐的唯一路径是缩短单会话占用时间，也就是压 T<sub>first</sub> 与 τ<sub>gen</sub>，而这又回到块长轴上。</p>\n<p>具体例子：若把首块压到极短，声码器启动次数上升，单会话占用时间未必下降——启动开销可能抵消首块缩短的收益。方案对负载的反向限制在这里显形：块长不能无限缩短，存在一个由声码器启动开销决定的下界，低于它则总占用时间反而上升。这个下界必须实测，材料未给出。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-11\">十一 · 可核查的测量口径清单</h3>\n<p>材料只给出机制描述，没有延迟、实时率与吞吐数字，因此本部分的可核查性只能落在“测什么、怎么切分”上，而不能落在具体数值上。下表把口径固定下来，供部署侧补测时对齐。</p>\n<table class=\"mini\"><thead><tr><th>口径</th><th>切分维度</th><th>对应代价</th></tr></thead><tbody>\n<tr><td>首包延迟 T<sub>first</sub></td><td>按会话、按轮次深度分桶，取 p50/p90/p99</td><td>用户感知开口时间</td></tr>\n<tr><td>四段分解</td><td>T<sub>asr</sub>、T<sub>dialog</sub>、T<sub>acoustic</sub><sup>first</sup>、T<sub>vocoder</sub><sup>first</sup> 分别计时</td><td>定位阻塞段</td></tr>\n<tr><td>实时率</td><td>逐块 τ<sub>gen</sub> 与 τ<sub>play</sub> 的比值分布</td><td>播放是否卡顿</td></tr>\n<tr><td>音画同步</td><td>相邻块推流时间戳抖动</td><td>口型表情偏移</td></tr>\n<tr><td>缓存占用</td><td>随会话深度与视觉帧率的增长曲线</td><td>显存与批大小上界</td></tr>\n<tr><td>块长敏感性</td><td>T<sub>first</sub> 与单会话占用时间随首块长度变化的曲线</td><td>块长下界的实测依据</td></tr>\n</tbody></table>\n<p>这张表的关键在于“按会话分桶”而非全局平均。全局平均会把深度会话的慢首包与首轮会话的快首包混在一起，得出一个既不代表尾部也不代表典型的值。分桶后，T<sub>first</sub> 的尾部来源才能被归因到具体段：是 T<sub>dialog</sub> 随 D 增长，还是 T<sub>vocoder</sub><sup>first</sup> 的启动开销，还是识别段的语音时长本身。</p>\n<p>公式上，单会话占用时间可以写成块数与单块耗时之积加上首块开销：</p>\n<div class=\"formula\">$$ T_{\\mathrm{session}} \\approx T_{\\mathrm{first}} + \\sum_{b=2}^{B} \\tau_{\\mathrm{gen}}^{(b)} $$</div>\n<p>这个式子说明：压 T<sub>first</sub> 只优化了第一项，若 B 因首块缩短而增大，第二项的块数上升可能吃掉收益。可核查的做法是同时记录 B 与逐块 τ<sub>gen</sub>，看总占用时间随首块长度的实际走向，而不是只看首包一个数。</p>\n<p>具体例子：把首块从“整段前半”缩到“一个短句”，T<sub>first</sub> 下降，但 B 从 2 增到 5，声码器启动 5 次而非 2 次；若单次启动开销显著，T<sub>session</sub> 可能不降反升。这正是“负载塑造方案、方案反过来限制负载”的闭环：块长不是自由参数，它被声码器启动开销与实时率裕度共同夹住。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-12\">十二 · 工程判断：把块长当作一等部署参数</h3>\n<p>在缺少硬件、量化与并行拓扑数据的前提下，ViDA-MAN 这条链路唯一能确定的部署判断是：块长（首块长度与后续块长）是一等参数，而不是实现细节。它同时出现在 T<sub>first</sub> 的加式里、实时率的不等式里、批边界的推导里、缓存占用的增长曲线里。任何容量规划若不把块长作为显式输入，就无法把首包延迟、吞吐与显存三者对齐到同一张表上。</p>\n<p>由此得出的工程动作是：先测块长敏感性曲线，再定 SLO，最后定并发与批大小。顺序不能反——先定并发再调块长，会把首包尾部误判为并发不足，从而错误地扩容。代价上，块长敏感性测试本身需要覆盖多轮深度与视觉帧率的组合，测试矩阵不小，但这是唯一能把“机制描述”转成“可核验锚点”的路径。材料未给出这些数值，因此本部分的结论停在口径与因果链上，具体阈值留给补测。</p>\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-13\">十三 · 首块声学表征的 kernel 形态与精度选择</h3>\n<p>ViDA-MAN 的声学生成器以流式方式逐块产出声学表征，首块优先返回。落到 Blackwell 上，这个“逐块”不是抽象概念，而是每块一次前向：块内是若干自回归步或一次并行解码，块间靠增量缓存衔接。首块 kernel 的形态决定了首包延迟的下界——首块越短，单次前向的 token 数越少，GEMM 的 M 维越小，越容易掉进“小 batch 低利用率”的坑。工程上的判断是：首块 kernel 不应追求单次大 GEMM 的峰值算力，而应追求低尾延迟，即把权重驻留、激活搬运与同步开销压到与计算同量级。</p>\n<p>精度选择直接改写这个平衡。FP16 与 BF16 在第五代 Tensor Core 上吞吐同级，BF16 动态范围更宽、更适合声学表征中偶发的尖峰激活，代价是尾数位少、低幅值细节的量化噪声略高；FP8（E4M3 存权重与激活、E5M2 存梯度类敏感量）把带宽需求减半，使首块 kernel 更早进入计算受限区；NVFP4 进一步把权重压到 4 位、配 FP8 的块缩放因子，显存与 L2 带宽收益最大，但对声学表征这种连续值回归任务，误差会集中体现在频谱细节上。ViDA-MAN 材料未给出量化方案，因此这里只能给出选型判据而非结论：首块延迟敏感、块长小，优先 BF16/FP16 保精度；后续块吞吐敏感，可切 FP8；NVFP4 只在声码器前的表征通道做受控试验。</p>\n<p>代价是显式的：精度每降一档，权重带宽近似减半，但误差补偿（缩放因子、残差通道、选择性高精度回退）会引入额外 kernel 与同步。以声学生成器单层权重矩阵为例，BF16 下每步搬运量与 FP8 下相差一倍，若首块只有数十个 token，搬运时间在总时长中占比上升，量化收益被小 GEMM 的低 occupancy 抵消。这正是首块不能盲目追低精度的机制原因。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-14\">十四 · 累加精度与误差如何在流式链路里累积</h3>\n<p>低精度乘法必须配高精度累加，否则误差随块数线性叠加。Blackwell 的 Tensor Core 在 FP8/NVFP4 输入下仍以 FP32 累加，这是数值稳定的底线；但累加器精度不等于结果精度，块缩放因子的选取、归约顺序、以及跨块缓存的重量化都会引入偏差。对流式声学生成，误差沿两个方向传播：块内沿自回归步传播，块间沿增量缓存传播。前者是单块内的条件分布漂移，后者是历史表征被反复读写、每次读写都可能经历一次量化往返。</p>\n<div class=\"formula\">$$ \\varepsilon_{\\text{total}} \\approx \\sum_{b=1}^{B} \\left( \\varepsilon_{\\text{quant}}^{(b)} + \\varepsilon_{\\text{accum}}^{(b)} \\right) + \\varepsilon_{\\text{cache}} \\cdot (B-1) $$</div>\n<p>逐项解释：$B$ 是流式块数；$\\varepsilon_{\\text{quant}}^{(b)}$ 是第 $b$ 块输入被压到 FP8/NVFP4 后的量化误差，与块内动态范围成正比；$\\varepsilon_{\\text{accum}}^{(b)}$ 是 FP32 累加器在长归约上的舍入误差，随归约长度增长但增长缓慢；$\\varepsilon_{\\text{cache}}$ 是增量缓存每次被重写回低精度格式时的往返误差，乘 $(B-1)$ 表示它在块间被反复施加。这个式子说明：块数越多，缓存往返项越主导；首块短、块数多，恰恰是最不利于低精度缓存的形态。</p>\n<p>工程代价落在显存与带宽上：若为压误差而把增量缓存保持 BF16，缓存占用翻倍，多轮对话下与视觉特征缓存叠加，直接压缩并发会话数；若缓存压到 FP8，则每轮都要承担一次往返误差。ViDA-MAN 材料只说明历史与视觉特征按轮次增量维护、未给缓存上限，因此这里的判断是机制性的：缓存精度应与块数挂钩，块数多的会话保留高精度缓存，块数少的会话才允许低精度压缩。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-15\">十五 · tcgen05 与 TMEM：把首块 kernel 的同步开销压下去</h3>\n<p>Blackwell 的 tcgen05 指令族把矩阵乘的累加器从寄存器文件搬到 Tensor Memory（TMEM），这是一块与 SM 紧耦合、专供 Tensor Core 读写的片上存储。对首块这种小 M 维 GEMM，传统路径的瓶颈往往不是乘加本身，而是累加器在寄存器与共享内存之间的搬运与同步；TMEM 让累加结果留在原地，后续 epilogue（缩放、激活、写回）直接从 TMEM 取数，减少了寄存器压力与 warp 间同步。对声学生成器，这意味着首块前向的尾延迟更可预测——尾延迟可预测比峰值算力更重要，因为首包延迟是四段之和，任何一段的长尾都会直接体现在用户听到第一个音素的时间上。</p>\n<p>代价同样明确：TMEM 容量有限，单 CTA 能驻留的累加器 tile 数受限，块内 token 数或隐藏维一旦超限就要分片，分片带来额外的 TMEM 读写与同步。首块若切得过短，TMEM 利用率不足；切得过长，又触发分片。这是一个由块长与隐藏维共同决定的权衡点，而 ViDA-MAN 材料未给出切块阈值，所以只能把它标为部署时必须实测的旋钮，而不是可引用的常数。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-16\">十六 · 2-SM MMA：用配对 SM 换首块吞吐还是换尾延迟</h3>\n<p>2-SM MMA 让两个 SM 协同完成一次更大的矩阵乘，把原本需要跨 CTA 分片的 K 维或 N 维合并到一次指令内，减少分片边界上的数据往返。对声学生成器这种隐藏维不小、但单步 token 数少的负载，2-SM MMA 的收益体现在：单次 MMA 覆盖更大 tile，减少了小 GEMM 反复启动的固定开销，从而压低首块的单步时间。但它要求两个 SM 的调度同步，配对失败或负载不均时，一个 SM 等另一个，尾延迟反而变差。</p>\n<p>系统代价是占用率：2-SM MMA 占用的 SM 对更多，并发会话数上升时，SM 对成为稀缺资源，批调度必须把“首块请求”和“后续块请求”分开排队——首块走 2-SM 抢尾延迟，后续块走单 SM 抢吞吐。这与连续批处理的常规做法相反，常规批处理倾向把所有请求混批以填满 SM；而首包优先的链路要求首块不能被后续块的长队阻塞。ViDA-MAN 的四段流水结构正好给了这个分层的依据：首块属于延迟关键路径，后续块属于吞吐路径。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-17\">十七 · 第五代 Tensor Core 的精度-吞吐曲线与声码器侧</h3>\n<p>第五代 Tensor Core 在 FP8 与 NVFP4 上给出更高的每周期乘加数，但这条曲线对声码器侧的意义与声学生成器不同。声码器把声学表征转成波形，是卷积/反卷积为主的负载，其 kernel 形态更接近固定形状的批量卷积，而非自回归小 GEMM。FP8 在声码器上的收益主要来自权重带宽减半，误差则体现在波形的高频细节与口型驱动的同步精度上——数字人口型由波形驱动，波形细节误差会转化为可见的口型抖动，这是视觉对话场景特有的代价，纯音频 TTS 不会暴露这一项。</p>\n<p>因此精度分层应按段划分：声学生成器首块保 BF16/FP16，后续块可试 FP8；声码器权重可 FP8，但输出波形与口型驱动信号应保留足够精度，避免音画同步误差被量化放大。ViDA-MAN 材料未给同步误差指标，这里只能给出机制判断：音画同步的误差预算应独立于音频质量预算，二者共用一套量化策略会把视觉侧的容差误当成音频侧的容差。</p>\n<table class=\"mini\"><thead><tr><th>段</th><th>精度取向</th><th>主要代价</th><th>机制风险</th></tr></thead><tbody><tr><td>首块声学生成</td><td>BF16/FP16</td><td>权重带宽高、SM 占用</td><td>小 GEMM occupancy 低</td></tr><tr><td>后续块生成</td><td>FP8 可试</td><td>缓存往返误差</td><td>块数多时误差累积</td></tr><tr><td>声码器</td><td>FP8 权重、输出保精度</td><td>波形细节误差</td><td>口型抖动、音画不同步</td></tr><tr><td>增量缓存</td><td>随块数分层</td><td>显存翻倍或往返误差</td><td>并发会话数被压缩</td></tr></tbody></table>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-18\">十八 · 把公式落到一次首包前向的伪代码思路</h3>\n<p>把上面的机制收束成一次首块前向的调度思路：权重按段预置精度，首块走 2-SM MMA 抢尾延迟，累加留在 TMEM，epilogue 在 TMEM 上完成缩放后直接写回 BF16 缓存；后续块切单 SM、FP8 权重、缓存按块数决定是否降精度。伪代码层面只需表达三件事：精度选择随段与块序变化、累加器驻留位置、以及首块与后续块的分流。</p>\n<div class=\"formula\">$$ T_{\\text{first}} = T_{\\text{asr}} + T_{\\text{dialog}} + \\max\\left(T_{\\text{acoustic}}^{\\text{first block}},\\ T_{\\text{prefetch}}\\right) + T_{\\text{vocoder}}^{\\text{first chunk}} $$</div>\n<p>逐项解释：前三项对应识别、对话与首块声学，末项是首块声码器。$\\max$ 项表示首块声学与权重/缓存预取可以重叠，预取若慢于计算则首包被预取拖住——这正是低精度权重带来的隐性收益：FP8/NVFP4 权重使预取更快完成，$\\max$ 更可能落在计算侧。但若首块过短、计算本身极快，$\\max$ 就由预取主导，此时继续压精度收益递减，反而应把预算花在缓存预取与声码器启动上。这个式子的工程含义是：首包优化不是单点压精度，而是找当前 $\\max$ 的主导项，逐段替换瓶颈。</p>\n<p>最终落在具体机制上：ViDA-MAN 的流式切块把首包延迟拆成四段可分别优化的路径，而 Blackwell 的 tcgen05/TMEM 与 2-SM MMA 改变的正是首块声学这一段内部的同步与尾延迟结构；精度分层则决定缓存往返误差与并发会话数的上限。材料未给硬件与量化数据，因此部署时的正确动作是先测出 $\\max$ 项落在哪一段，再决定该段用 BF16 保尾延迟还是用 FP8/NVFP4 换预取与带宽，而不是把某一档精度当作全局默认。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-19\">十九 · 首块优先的边界：流式切块、声码器阻塞与增量缓存的代价</h3>\n<p>ViDA-MAN 的数值精度选择不能脱离它的流水结构单独讨论。首包时间由四段相加决定，其中声学生成器与声码器只处理首块，因此首块的 token 数（或帧数）直接决定这两段在关键路径上的长度。若把首块切得过短以压低 <span class=\"formula-inline\">T_acoustic^first block</span>，声学模型需要在极少的上下文里给出可懂的音素序列，声码器也要在不足一个完整音节的表征上重建波形，音质与韵律稳定性下降；若切得过长，首包延迟被线性拉长，且首块内部的注意力计算无法与后续块重叠。工程上的可行边界是：首块长度取一个语义单元（短句或短语）而非固定帧数，后续块按固定节奏推进，使声码器在首块合成期间就能拿到第二块表征，形成流水重叠。</p>\n<p>累加精度在这里的代价不对称。声学生成器的自回归逐帧输出对数值误差敏感——表征漂移到声码器侧会表现为爆音或口型抖动，因此声学侧通常保留 FP16/BF16 激活与 FP32 累加；而声码器是前馈卷积/上采样结构，对精度容忍度高，可用 FP8 甚至 NVFP4 权重配合 FP16 激活，把显存带宽压力从声码器侧释放。误差传播可写成逐块累积形式：</p>\n<div class=\"formula\">$$ \\epsilon_{\\mathrm{block}} = \\sum_{k=1}^{K} \\left( \\prod_{j=k+1}^{K} \\|J_j\\| \\right) \\delta_k $$</div>\n<p>其中 <span class=\"formula-inline\">δ_k</span> 是第 k 块量化引入的扰动，<span class=\"formula-inline\">J_j</span> 是块间声学状态转移的雅可比。自回归链越长，谱半径越接近 1，早期块的误差被放大得越明显——这正是首块必须用高精度、后续块才敢降精度的原因。Blackwell 的 tcgen05 与 TMEM 让 2-SM MMA 在 FP8 下保持 FP32 累加，使声码器侧的降精度不牺牲累加稳定性；但 2-SM 协作要求两个 SM 的 tile 尺寸对齐，首块过短时 tile 填充率下降，MMA 利用率反而变差，这是短首块在 Blackwell 上的隐性代价。</p>\n<p>增量缓存是另一条边界。对话历史与视觉特征按轮次增量维护，避免了整段重算，但缓存随轮次单调增长，显存占用与每轮注意力的读取带宽同步上升。多轮视觉对话中视觉特征往往是最大项，若不做淘汰，长会话会把 KV 与视觉缓存推到显存上限，迫使批调度降低并发。失效条件很具体：当缓存增长使单会话显存超过 NVL72 单 GPU 可用余量时，连续批处理只能退回小批或跨卡切分，首包延迟因通信与排队而抬高。监控上应把首块长度、声码器队列深度与缓存字节数作为三个独立指标采集——只优化声学生成侧会低估端到端首包时间，声码器阻塞在机制上是最直接的风险点。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>精度取向</th><th>系统代价</th></tr></thead><tbody><tr><td>声学生成（自回归）</td><td>FP16/BF16 激活，FP32 累加</td><td>首块在关键路径，精度降级直接损音质</td></tr><tr><td>声码器（前馈）</td><td>FP8/NVFP4 权重，FP16 激活</td><td>降精度释放带宽，但短首块使 2-SM tile 填充率下降</td></tr><tr><td>历史与视觉缓存</td><td>增量维护，精度随特征类型</td><td>随轮次增长，压缩并发与首包排队</td></tr></tbody></table>\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-20\">二十 · 显存账本的四个抽屉与可复算基线</h3>\n<p>把 ViDA-MAN 的四段流水（识别、对话、声学生成、声码器）落到一张 HBM 账本上，显存只花在四类对象上：权重、激活、KV/历史缓存、以及流式推流所需的中间缓冲。论文卡没有给出参数量与量化方案，所以账本必须写成参数化形式，让读者代入自己的模型规模即可复算。设声学生成器参数量为 <span class=\"inline-math\">P<sub>a</sub></span>、声码器为 <span class=\"inline-math\">P<sub>v</sub></span>、对话管理器（含多模态融合层）为 <span class=\"inline-math\">P<sub>d</sub></span>、语音前端为 <span class=\"inline-math\">P<sub>s</sub></span>，每参数字节数为 <span class=\"inline-math\">b<sub>w</sub></span>（BF16 为 2，FP8 为 1，NVFP4 为 0.5 加缩放因子开销），则权重占用为：</p>\n<div class=\"formula\">$$ M_{\\mathrm{weight}} = b_w \\cdot (P_a + P_v + P_d + P_s) + M_{\\mathrm{scale}} $$</div>\n<p>其中 <span class=\"inline-math\">M<sub>scale</sub></span> 在 NVFP4 下不可忽略：每 16 个元素共享一个 FP8 缩放因子，等效额外约 6% 的字节开销，且 tcgen05 的 MMA 要求缩放因子按 TMEM 布局对齐，实际占用比理论值略高。激活侧的关键是流式切块：声学生成器一次只处理一个语义块，激活峰值由块长 <span class=\"inline-math\">L<sub>blk</sub></span>、隐藏维度 <span class=\"inline-math\">d</span></span>、层数 <span class=\"inline-math\">N<sub>L</sub></span> 与批内并发会话数 <span class=\"inline-math\">B</span> 共同决定，粗略为 <span class=\"inline-math\">B · L<sub>blk</sub> · d · N<sub>L</sub> · b<sub>act</sub></span> 再乘一个与注意力实现相关的系数。这正是流式切块对显存的直接代价：块越长，首包延迟越高，但激活峰值也越高；块越短，激活省了，声学生成器的调用次数与调度开销上升。工程判断是先把 <span class=\"inline-math\">L<sub>blk</sub></span> 压到能维持实时率的最小值，再用连续批处理把 <span class=\"inline-math\">B</span> 填满，而不是反过来。</p>\n<p>具体例子：假设 <span class=\"inline-math\">P<sub>a</sub></span>=1.5B、<span class=\"inline-math\">P<sub>v</sub></span>=0.1B、<span class=\"inline-math\">P<sub>d</sub></span>=0.5B、<span class=\"inline-math\">P<sub>s</sub></span>=0.3B，BF16 下权重约 4.8 GB；换 FP8 降到 2.4 GB，换 NVFP4 约 1.3 GB 加缩放开销。单张 B200 的 HBM3e 容量足以把全部权重放进一张卡，这意味着 ViDA-MAN 这类系统的容量规划矛盾不在权重，而在 KV 与历史缓存随并发会话线性增长。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-21\">二十一 · 历史与视觉特征的 KV 账本：增量维护不等于不增长</h3>\n<p>对话管理器按轮次增量维护历史与视觉特征，避免整段重算，但增量维护只省了计算，不省显存。每一轮的文本 token 与当前视频帧特征都要以 KV 形式驻留，供后续轮次注意力回看。设第 <span class=\"inline-math\">i</span> 轮文本 token 数为 <span class=\"inline-math\">n<sub>t,i</sub></span>、视觉特征 token 数为 <span class=\"inline-math\">n<sub>v,i</sub></span>、对话模型层数为 <span class=\"inline-math\">N<sub>d</sub></span>、KV 头数为 <span class=\"inline-math\">H<sub>kv</sub></span>、头维度为 <span class=\"inline-math\">d<sub>h</sub></span>、KV 每元素字节为 <span class=\"inline-math\">b<sub>kv</sub></span>，则单会话到第 <span class=\"inline-math\">R</span> 轮的 KV 占用为：</p>\n<div class=\"formula\">$$ M_{\\mathrm{kv}}(R) = 2 \\cdot b_{kv} \\cdot N_d \\cdot H_{kv} \\cdot d_h \\cdot \\sum_{i=1}^{R} (n_{t,i} + n_{v,i}) $$</div>\n<p>系数 2 来自 K 与 V 两份。视觉特征是这里的隐性大头：一帧画面的特征 token 数往往远大于一轮回复文本的 token 数，而多轮对话中用户可能持续上传画面。若不做压缩，<span class=\"inline-math\">M<sub>kv</sub></span> 随轮次线性上涨，并发会话数一多就把 HBM 吃满。三种工程手段各有代价：其一，视觉特征跨轮复用——同一场景的帧特征做池化或降采样后再入 KV，省显存但损失细粒度视觉 grounding；其二，历史窗口截断加摘要——把早期轮次压成一段文本摘要替换原 KV，省显存但引入一次额外的生成调用，抬高该轮的首包时间；其三，KV 量化到 FP8——<span class=\"inline-math\">b<sub>kv</sub></span> 减半，代价是注意力分数精度下降，长历史下容易出现回复漂移。</p>\n<p>带宽侧的判断更关键。解码阶段每生成一个 token 要把全部 KV 读一遍，单 token 的 KV 读取量为 <span class=\"inline-math\">2 · b<sub>kv</sub> · N<sub>d</sub> · H<sub>kv</sub> · d<sub>h</sub> · L<sub>ctx</sub></span>，其中 <span class=\"inline-math\">L<sub>ctx</sub></span> 是当前上下文长度。这正是解码的带宽瓶颈所在：算术强度极低，HBM3e 的带宽被 KV 读取吃满，而 tensor core 大量闲置。B200 这一档的 HBM3e 带宽相对前代提升明显，但 KV 读取量随上下文线性增长，带宽红利会被长历史抵消。因此对 ViDA-MAN 而言，压缩视觉特征 token 数与截断历史不只是省容量，更是直接抬高解码吞吐的手段。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-22\">二十二 · 分页与复用：PagedAttention 在流式场景的变体</h3>\n<p>连续批处理下，各会话的 KV 长度不一且随轮次增长，若按最大长度预分配，碎片浪费可达数倍。分页 KV cache 把 KV 切成固定大小的块（如 16 个 token 一块），用块表做逻辑到物理的映射，按需分配。ViDA-MAN 的特殊之处在于两类 KV 的生命周期不同：文本历史的块随轮次追加，视觉特征的块在同一场景内可被多个会话共享。于是可以引入块级引用计数：同一视频帧特征被多个会话引用时只存一份物理块，引用计数归零才回收。这在多用户观看同一路视频的数字人客服场景里收益直接——显存占用从 <span class=\"inline-math\">B · M<sub>v</sub></span> 降到 <span class=\"inline-math\">M<sub>v</sub></span> 加少量块表开销。</p>\n<p>复用还有一层：前缀缓存。系统提示、数字人形象描述、固定的对话策略文本在各会话间完全相同，其 KV 块可跨请求复用，跳过预填。代价是块表的查找与命中判断带来少量调度开销，且前缀一旦变化就要失效重算。工程上要把前缀切成稳定段与可变段，稳定段做跨会话共享，可变段按会话私有分页。分页的另一个代价是块大小与注意力核的匹配：块太小则块表膨胀、核启动频繁；块太大则尾部浪费。对流式声学生成器，块大小还要与语义块边界对齐，否则一个语义块跨两个 KV 块，增量维护的写放大明显。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-23\">二十三 · 卸载与压缩：把冷历史赶出 HBM</h3>\n<p>当并发会话数超过单卡容量，最直接的手段是把冷历史卸载到主机内存甚至 NVMe，需要时再换入。卸载的代价是 PCIe 往返延迟与带宽，对首包延迟是致命的——若首块声学生成需要回看被卸载的历史，首包时间会被一次换入拉长。因此卸载策略必须与流式切块配合：首块只依赖最近若干轮的热历史与当前视觉特征，热历史常驻 HBM；更早的轮次在生成后续块时才按需换入，此时首包已经推出，用户感知不到。这就是把 <span class=\"inline-math\">T<sub>first</sub></span> 与后续块的推进节奏解耦的显存侧对应手段。</p>\n<p>压缩的另一条路是量化 KV 与视觉特征。视觉特征本身是高维连续向量，做 FP8 或 INT8 量化的精度损失比文本 KV 更敏感，因为口型与表情驱动依赖视觉特征的细粒度信息。工程判断是：文本 KV 可量化到 FP8，视觉特征优先做 token 级降采样（如时间维池化、空间维 patch 合并）而非数值量化，前者省的是块数，后者省的是每元素字节，前者对下游任务的破坏通常更可控。卸载与压缩都不是免费的：卸载吃 PCIe 带宽与延迟，压缩吃精度，两者都要在 SLO 里折算成首包延迟与实时率的预算项。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-24\">二十四 · HBM3e 容量怎么算：一个可复算的预算表</h3>\n<p>把上面的账本收拢成一张可代入的表。以单张 B200 档 GPU 为例，容量记为 <span class=\"inline-math\">C</span>（按 HBM3e 实际可用容量扣除驱动与框架开销后的值，具体数值以器件规格为准，此处不引具体数字），预算约束为：</p>\n<div class=\"formula\">$$ M_{\\mathrm{weight}} + M_{\\mathrm{act}}^{\\max} + B \\cdot M_{\\mathrm{kv}}^{\\mathrm{hot}} + M_{\\mathrm{shared}} + M_{\\mathrm{reserve}} \\le C $$</div>\n<p>其中 <span class=\"inline-math\">M<sub>shared</sub></span> 是跨会话共享的前缀与视觉特征块，<span class=\"inline-math\">M<sub>reserve</sub></span> 是留给通信缓冲（NVLink 5 上的集合通信、NIXL 传输）与碎片的安全余量。给定权重与激活后，可解出并发会话上限：</p>\n<div class=\"formula\">$$ B_{\\max} = \\left\\lfloor \\frac{C - M_{\\mathrm{weight}} - M_{\\mathrm{act}}^{\\max} - M_{\\mathrm{shared}} - M_{\\mathrm{reserve}}}{M_{\\mathrm{kv}}^{\\mathrm{hot}}} \\right\\rfloor $$</div>\n<table class=\"mini\"><thead><tr><th>账本项</th><th>驱动因素</th><th>主要代价</th><th>压缩手段</th></tr></thead><tbody><tr><td>权重</td><td>四模块参数量、量化位宽</td><td>容量；解码时每 token 读一遍，吃带宽</td><td>FP8/NVFP4、模块间分卡</td></tr><tr><td>激活</td><td>块长、并发批、层数</td><td>峰值容量；块长直接进首包延迟</td><td>缩短块长、连续批处理填批</td></tr><tr><td>KV 热历史</td><td>轮次、视觉 token 数、层数</td><td>随并发线性增长；解码带宽瓶颈</td><td>分页、前缀共享、FP8 KV</td></tr><tr><td>共享块</td><td>同路视频会话数</td><td>块表查找开销</td><td>引用计数、稳定前缀切分</td></tr><tr><td>卸载冷历史</td><td>超出 HBM 的轮次</td><td>PCIe 延迟与带宽，影响后续块而非首包</td><td>热/冷分层、按需换入</td></tr></tbody></table>\n<p>具体例子：若 <span class=\"inline-math\">M<sub>weight</sub></span> 取 FP8 下的 2.4 GB、<span class=\"inline-math\">M<sub>act</sub></span> 取 2 GB、共享块 1 GB、余量 4 GB，则留给 KV 的空间是 <span class=\"inline-math\">C − 9.4 GB</span>。若单会话热 KV 为 200 MB，则并发上限约 <span class=\"inline-math\">(C − 9.4)/0.2</span> 个会话。这个式子把容量规划从“感觉”变成可复算的除法：任何一项涨了，并发就按比例掉。工程上要盯的是 <span class=\"inline-math\">M<sub>kv</sub><sup>hot</sup></span> 随轮次的斜率——它决定系统在长对话下是线性退化还是断崖。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-25\">二十五 · 带宽瓶颈的落点与工程判断</h3>\n<p>ViDA-MAN 的推理链路上有两个带宽热点。其一是对话管理器的解码：KV 读取随上下文线性增长，算术强度低，HBM3e 带宽是硬约束；对策是压缩视觉 token、截断历史、FP8 KV，把每 token 的读取字节压下来。其二是声码器：它把声学表征转成波形，是逐块的高频操作，若声码器与声学生成器分卡部署，块级表征要跨 NVLink 5 传输，块越小传输次数越多，链路开销占比越高。这就是流式切块的隐藏代价：切块换首包延迟，但切得太碎会把带宽与调度开销推到前台。音画同步还要求声码器输出与口型驱动节奏对齐，缓冲区的深度直接吃显存，缓冲越深抗抖动越强、显存与延迟越大。</p>\n<p>落到 Blackwell 档位的工程判断有三条。第一，权重不是矛盾，KV 与视觉特征是矛盾，容量规划应围绕 <span class=\"inline-math\">B<sub>max</sub></span> 的除法展开，而不是围绕参数量。第二，tcgen05 与 TMEM 的收益集中在声学生成器的矩阵乘上，但解码阶段被 KV 读取带宽卡住时，tensor core 的提升无法兑现为吞吐，必须先做 KV 压缩再谈算力。第三，卸载与分页要和流式切块联合设计：首块只碰热数据，冷数据在后续块推进时换入，把换入延迟藏进已经推流的时段里。论文卡没有给出任何延迟、实时率与并发数字，因此以上账本只能作为部署前的估算框架，真实容量必须用首包延迟与实时率两项 SLO 反推 <span class=\"inline-math\">B<sub>max</sub></span> 后再实测校准。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-26\">二十六 · 流式语音合成下的显存账本与首包边界</h3>\n<p>ViDA-MAN 的显存账本不能按“整段对话一次性编码”来算，因为它的语音合成侧是流式声学生成加声码器两段推进：首块声学表征一出来就交给声码器推流，后续块边生成边补齐。这意味着显存占用在时间轴上是被切碎的——声学生成器只需持有当前块的自回归状态与已生成块的历史，声码器只需持有首块对应的波形缓冲。真正随轮次增长的是对话管理器里的多轮历史与视觉特征缓存，而材料明确说这两者按轮次增量维护、避免整段重算，但未给出缓存上限与淘汰策略。于是边界条件很清楚：只要增量缓存的增长速率超过单轮释放速率，显存就会在多轮后单调抬升，首包延迟的第四段（声码器首块）也会因为等待调度而变长。</p>\n<p>可复算的预算形式是：设每轮新增历史 token 数为 <span class=\"inline-math\">\\(n_h\\)</span>、视觉特征每帧维度为 <span class=\"inline-math\">\\(d_v\\)</span>、缓存精度字节数为 <span class=\"inline-math\">\\(b\\)</span>、并发会话数为 <span class=\"inline-math\">\\(C\\)</span>、保留轮数为 <span class=\"inline-math\">\\(R\\)</span>，则对话与视觉缓存的下界为</p>\n<div class=\"formula\">$$ M_{\\mathrm{cache}} \\ge C \\cdot R \\cdot (n_h + d_v) \\cdot b $$</div>\n<p>这个式子只给出下界，因为声学生成器的自回归状态、声码器的重叠缓冲、以及首块优先策略下为后续块预留的推流队列都要额外计入。工程判断落在 <span class=\"inline-math\">\\(R\\)</span> 上：材料没有给出淘汰规则，所以 <span class=\"inline-math\">\\(R\\)</span> 若取“全部历史”，<span class=\"inline-math\">\\(M_{\\mathrm{cache}}\\)</span> 随轮次线性无界；若取固定窗口，则要接受旧轮视觉特征被丢弃后对话理解质量的下降。这是本方案最直接的失效条件——缓存策略缺失时，显存账本无法闭合。</p>\n<p>带宽瓶颈不在声码器，而在声学生成器的逐块自回归解码：每生成一个声学帧都要读一次权重与当前块的 KV 状态，属于典型的低算术强度、权重带宽受限形态。Blackwell 档位上若把声学模型权重压到 FP8/NVFP4，权重读取字节数下降，但 KV 状态的读写仍按块推进，块越短则单位时间内的状态读写次数越多，带宽压力反而上升。首块长度因此是一个双向约束：块太长抬高 <span class=\"inline-math\">\\(T_{\\mathrm{acoustic}}^{\\mathrm{first\\ block}}\\)</span>，块太短抬高单位帧的 KV 带宽开销。材料未给出切块阈值，所以只能把首块长度当作待标定参数，而不是可引用的固定值。</p>\n<table class=\"mini\"><thead><tr><th>显存项</th><th>随轮次增长</th><th>随并发增长</th><th>失效触发点</th></tr></thead><tbody><tr><td>对话历史 + 视觉特征缓存</td><td>是（无淘汰则无界）</td><td>线性</td><td>缺淘汰策略</td></tr><tr><td>声学生成器 KV / 自回归状态</td><td>否（按块滚动）</td><td>线性</td><td>块过短致带宽饱和</td></tr><tr><td>声码器波形与推流缓冲</td><td>否</td><td>线性</td><td>首块阻塞拖长首包</td></tr></tbody></table>\n<p>把这张表代回首包公式 <span class=\"inline-math\">\\(T_{\\mathrm{first}} = T_{\\mathrm{asr}} + T_{\\mathrm{dialog}} + T_{\\mathrm{acoustic}}^{\\mathrm{first\\ block}} + T_{\\mathrm{vocoder}}^{\\mathrm{first\\ chunk}}\\)</span>，可以看到显存压力与首包延迟是耦合的：缓存膨胀会挤占声码器可用的显存与带宽，使第四段变长；而首块过长又会直接抬高第三段。材料没有给出任何延迟、实时率或并发数字，也没有说明是否使用 B200/B300/GB200 NVL72 与 NVFP4/FP8，因此这套账本只能作为容量规划的骨架，具体系数必须在目标硬件上补测后才能闭合。音画同步同样落在这条线上——口型与表情由声码器输出波形驱动，首块与后续块的推流节奏一旦被显存调度打断，同步误差就会累积，而材料未给出同步误差指标。</p>\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-27\">二十七 · 四段流水上的调度对象与代价函数</h3>\n<p>ViDA-MAN 的推理链路是识别、对话、声学生成、声码器四段串联，首包延迟按 <span class=\"formula\">$$ T_{\\mathrm{first}} = T_{\\mathrm{asr}} + T_{\\mathrm{dialog}} + T_{\\mathrm{acoustic}}^{\\mathrm{first\\ block}} + T_{\\mathrm{vocoder}}^{\\mathrm{first\\ chunk}} $$</span> 逐项相加。调度器真正要管的不是“一个请求”，而是这条链上四个可独立排队、独立抢占的作业：ASR 的流式解码步、对话管理器的多模态前向、声学生成器的逐块自回归步、声码器的逐块上采样。四段里前三段是计算密集的 token 级自回归，第四段是带宽密集的波形合成，它们的资源画像完全不同，混在一个 FIFO 队列里必然出现“声码器等生成器、生成器等对话”的链式阻塞。工程上第一步是把这四段拆成独立的执行队列，各自持有自己的批处理窗口与准入阈值；第二步是给每个队列定义代价函数，而不是统一用“平均延迟”。对首包敏感的是 <span class=\"formula\">$$ \\text{priority} \\propto \\frac{1}{T_{\\mathrm{first}}^{\\mathrm{remaining}}} $$</span>，即剩余首包预算越小的请求越优先；对后续块敏感的是实时率 RTF，要求生成速度持续快于播放速度，否则客户端缓冲会被抽干。这两类目标在同一个 GPU 上争夺 SM 与显存带宽，调度策略必须显式区分“抢首包”和“保稳态”两个阶段。</p>\n<p>具体机制上，对话管理器与声学生成器共享同一块多模态上下文（历史文本 token 与视觉特征），但它们的批处理维度不同：对话侧按轮次批量拼接历史，声学侧按语义块增量推进。若把两者放进同一个连续批处理循环，视觉特征的长序列会挤占声学侧的首块窗口，直接抬高 <span class=\"formula\">$$T_{\\mathrm{acoustic}}^{\\mathrm{first\\ block}}$$</span>。代价体现在显存上：视觉特征按轮次增量缓存，缓存上限未给出，但每一轮新增的视觉 token 都会与历史 token 一起参与注意力计算，KV 占用随轮次单调增长；在并发会话数上升时，这部分缓存是抢占时最先被牺牲的对象。一个具体例子：某会话首轮视觉特征较长，若调度器把该会话与另外若干长历史会话编入同一批，首块声学生成的等待时间被拉长，用户听到第一个音节的时刻明显后移——这正是四段串联下“批越大首包越慢”的典型形态。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-28\">二十八 · 连续批处理：按块而非按请求做调度单位</h3>\n<p>连续批处理（continuous batching）在自回归解码里的标准做法是每步重排 batch，把已完成的序列踢出、把新到达的序列插入。放到 ViDA-MAN 的流式合成上，调度单位应当从“请求”下沉到“语义块”：一个会话的回复文本被切成若干块，每块是一次独立的声学生成作业，块与块之间有依赖（后块依赖前块的声学上下文），但块与块之间可以与其他会话的块交错执行。伪代码思路是维护一个按块组织的就绪队列：</p>\n<div class=\"formula\">$$\\text{for each step: } \\mathcal{B} \\leftarrow \\text{top-}k(\\text{ready blocks by } T_{\\mathrm{first}}^{\\mathrm{remaining}}),\\ \\text{evict finished},\\ \\text{admit new first blocks}$$</div>\n<p>关键约束是首块不能被后续块无限期插队。若只用“最早到达优先”，一个已经进入稳态的长会话会持续产出后续块，把新会话的首块挤到队尾，尾延迟（p99 首包）随之恶化。可行做法是给首块保留固定配额：每步的 batch 中划出若干槽位专供首块，剩余槽位给后续块填满，这样稳态吞吐不塌、首包又有上界。代价是 GPU 利用率在首块槽位空闲时下降，表现为 SM 占用率的锯齿；在 Blackwell 这类大芯片上，槽位空转的绝对浪费比小芯片更明显，因此配额比例要按并发会话数与首块到达率调，而不是拍一个固定值。吞吐侧的收益来自块级交错：声码器的带宽密集段与声学生成的计算密集段可以在时间上重叠，避免声码器整段空等。</p>\n<p>另一个机制点是块边界与 KV 的对应关系。声学生成器逐块推进时，每块结束后其 KV 需要保留以供后续块续接；连续批处理在踢出已完成块时，必须区分“该会话本轮已完结”与“该会话还有后续块”，前者可释放 KV，后者必须保留。若混淆两者，会话在块间被误踢，下一块就要重算上下文，首包之外的稳态延迟出现尖刺。显存代价由此转化为调度正确性问题：KV 的释放时机由块依赖图决定，而不是由 batch 槽位决定。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-29\">二十九 · Chunked prefill：把长上下文切开喂给首块</h3>\n<p>ViDA-MAN 的首块声学生成需要先“读入”对话管理器给出的多模态上下文——历史文本与视觉特征。这段上下文长度随轮次增长，若一次性做完整 prefill，首块的等待时间被 prefill 主导，<span class=\"formula\">$$T_{\\mathrm{acoustic}}^{\\mathrm{first\\ block}}$$</span> 随轮次线性上升。chunked prefill 的做法是把这段上下文切成若干 chunk，与解码步混编进同一个 batch：每个调度步既处理一个 prefill chunk，也推进若干已在解码的块。这样 prefill 的长尾被摊平到多个步里，单步时延可控，首块不必等整段上下文读完才开始出表征。</p>\n<p>代价是首块的“有效上下文”在开始时并不完整：若首块表征依赖视觉特征的全局注意力，切 chunk 会让首块在上下文未读全时就生成，损害音画一致性。工程判断是分层处理——把对话历史与视觉特征中对首块最关键的近期片段放进第一个 chunk，远端历史放进后续 chunk 并与首块之后的生成重叠。这样首块拿到的是“够用的上下文”，而不是“完整的上下文”。吞吐上，chunked prefill 让 prefill 与 decode 共享 SM，避免了 prefill 阶段的纯计算波峰把 decode 的实时率打穿；代价是 decode 步的 batch 被 prefill chunk 稀释，单步推进的 token 数下降，稳态 RTF 略微变差。这个取舍在并发高、轮次深时偏向 chunked prefill，在并发低、首包预算紧时偏向整段 prefill 加首块优先。</p>\n<p>具体例子：某会话进入第五轮，历史文本与视觉特征合起来远超首轮；若整段 prefill，首块要等全部注意力算完；若按 chunk 切分并把近期视觉帧前置，首块在第一个 chunk 完成后即可启动，后续 chunk 与首块之后的声学生成并行推进。材料未给出 chunk 大小阈值，因此调度器应把 chunk 长度作为可调参数暴露给容量规划，而不是写死。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-30\">三十 · 优先级与抢占：谁让路、让多少</h3>\n<p>优先级体系要覆盖两个维度：会话级（新会话首包 vs 老会话稳态）与块级（首块 vs 后续块）。抢占的粒度决定代价：抢占一个正在解码的块，意味着它的 KV 要换出到主机内存或直接丢弃重算；抢占一个尚未开始的块，只是队列重排，几乎无代价。因此调度器应优先抢占“未启动的后续块”，把正在执行的块跑完再让路，避免 KV 换出带来的带宽开销——在 NVLink 5 与 HBM 之间搬 KV 的代价远高于重排队列。</p>\n<p>公式上，抢占判据可以写成收益与代价的比较：<span class=\"formula\">$$\\text{preempt if } \\Delta T_{\\mathrm{first}}^{\\mathrm{saved}} &gt; \\Delta T_{\\mathrm{steady}}^{\\mathrm{penalty}} + c_{\\mathrm{kv\\ swap}}$$</span>，其中换出代价与 KV 字节数成正比。对 ViDA-MAN 而言，视觉特征的 KV 往往比文本历史大得多，抢占一个带长视觉上下文的会话代价高，调度器应倾向抢占文本历史长但视觉特征短的会话。显存侧的连锁反应是：被抢占会话的 KV 若不能及时换回，其后续块在恢复时要么重算 prefill，要么等待换入，两者都抬高尾延迟。因此抢占策略必须与缓存淘汰策略联动——材料未给出淘汰规则，工程上应按“最近被抢占且恢复概率低”的顺序淘汰，而不是按 LRU 一刀切。</p>\n<p>尾延迟的压制还依赖准入控制：当首块队列深度超过阈值时，新会话不应被无条件接纳，而应排队或降级（例如先返回文本、后补语音）。这与分离式预填/解码的准入逻辑同源。具体例子：并发会话数上升时，若不加准入，首块槽位被填满，p99 首包随队列深度线性恶化；加一个按 <span class=\"formula\">$$T_{\\mathrm{first}}^{\\mathrm{remaining}}$$</span> 排序的短队列，把超出预算的会话挡在门外，p99 被钉在预算附近，代价是部分会话的首次响应被推迟——这是可接受的工程折衷，因为数字人对话的语义允许“稍后开口”。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-31\">三十一 · 分离式预填/解码与声码器的带宽账</h3>\n<p>分离式预填/解码（disaggregated prefill/decode）在 ViDA-MAN 上的映射不是简单的两段切分，而是四段里“计算密集段”与“带宽密集段”的分离：ASR、对话、声学生成属于计算与显存带宽混合型，声码器属于纯带宽型。把声码器放到独立的执行资源上，可以让声学生成器持续占用 SM 做自回归，而声码器在自己的窗口里按块消费声学表征，两者通过块级队列解耦。收益是首块声码器合成不再与下一块声学生成争抢同一批 SM；代价是块在队列里的传输时延，以及声码器侧需要维持足够的块缓冲以吸收生成侧的抖动。</p>\n<p>带宽账要算清楚：声码器把声学表征转成波形，输出采样率与块长决定单位时间的波形字节数，这部分是持续的写带宽；声学生成器每步要读 KV、写新 KV，是读带宽为主。两者叠加时，HBM 带宽成为共享瓶颈，分离部署若不在同一芯片上，跨芯片传输又引入额外开销。工程判断是：声码器与声学生成器放在同一 GPU 但不同 SM 分区，块通过片上或 HBM 中转，避免跨节点；只有在并发极高、单芯片带宽被打满时才考虑物理分离，并接受传输时延对首包的抬升。音画同步依赖首块与后续块的推流节奏，声码器侧的块缓冲深度直接决定口型与语音的对齐误差——缓冲越深越平滑，但首包越晚，这个取舍与首块长度共同构成音画同步的两个旋钮。</p>\n<p>具体例子：若声码器被后续块占满，首块排在其后，<span class=\"formula\">$$T_{\\mathrm{vocoder}}^{\\mathrm{first\\ chunk}}$$</span> 被拉长，端到端首包直接受损；反之若给首块预留声码器窗口，稳态下声码器利用率下降但首包有界。这正是“首包优先”与“稳态吞吐”在同一硬件上的正面冲突，调度器必须显式选择而非默认平均分配。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-32\">三十二 · 时延与吞吐的取舍落点</h3>\n<p>把上述机制合起来看，ViDA-MAN 的调度取舍落在三个可调参数上：首块槽位配额、chunk 长度、声码器缓冲深度。三者共同决定首包延迟的上界与稳态 RTF 的下界。容量规划时应把首包预算按四段拆解分配，而不是给整条链一个总数——因为任一环节阻塞都会直接抬高首包时间，拆解后才能定位是 ASR 排队、对话 prefill 过长、首块生成慢还是声码器被占。材料未给出具体延迟与并发数字，因此这些参数只能以机制关系约束：首块槽位配额随并发上升而收紧，chunk 长度随轮次深度上升而缩短，声码器缓冲深度随音画同步要求上升而加深。尾延迟的压制不靠单点优化，而靠准入控制加首块配额加块级抢占三件事同时到位；缺任何一件，p99 首包都会在负载上升时失守。</p>\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-33\">三十三 · 从四段流水反推切分边界</h3>\n<p>ViDA-MAN 的推理链路被拆成识别、对话、声学生成、声码器四段，这个结构本身就是并行切分的依据：四段之间是流水线关系，段内才有张量并行或专家并行的空间。工程上先问一个问题——哪一段是流水线的“窄口”。首包延迟公式给出的是串联和：</p>\n<div class=\"formula\">$$ T_{\\mathrm{first}} = T_{\\mathrm{asr}} + T_{\\mathrm{dialog}} + T_{\\mathrm{acoustic}}^{\\mathrm{first\\ block}} + T_{\\mathrm{vocoder}}^{\\mathrm{first\\ chunk}} $$</div>\n<p>串联结构意味着任何一段的并行化收益都被其余三段稀释。若把声学生成器从单卡扩到 8 卡 TP，其首块耗时降到原来的几分之一，但只要声码器首块仍是串行阻塞，端到端首包时间的下降幅度就受限于声码器占比。因此切分策略必须按“段内并行度 × 该段在首包中的占比”排序：对话管理器承载多轮历史与视觉特征，通常是显存与计算双重压力点，适合 TP/PP；声学生成器是自回归逐块推进，适合 TP 加 EP（若采用 MoE 声学骨干）；声码器是短时卷积或流式反卷积结构，切分收益低，更适合 DP 复制以承接并发。ViDA-MAN 材料未给出并行拓扑，这一判断只能落在机制层：切分边界应沿流水线段落划分，而不是把整条链路当成一个可任意切分的单体模型。</p>\n<p>代价上要盯住一个量：流水线气泡。PP 把声学生成器按层切成若干 stage，stage 之间的激活传输与同步等待会引入空转；在流式场景里，气泡直接表现为首块产出被推迟。对首包敏感的系统，PP 的 stage 数应压到最小，宁可把并行度投到 TP 上换取单 stage 内的低延迟。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-34\">三十四 · NVLink 5 与 NVSwitch：域内带宽决定 TP 上限</h3>\n<p>Blackwell 档位的 GB200/GB300 NVL72 把 72 颗 GPU 置于同一 NVLink 域内，NVSwitch 提供全互联，NVLink 5 的每 GPU 双向带宽远高于 PCIe 代际。这条事实的工程含义是：TP 的通信量随并行度线性增长，而域内带宽决定了 TP 能扩到多大而不被 All-Reduce 拖垮。以单层 Transformer 的 TP 为例，前向每层需要两次 All-Reduce（注意力输出投影后与 MLP 下投影后），单次通信量为：</p>\n<div class=\"formula\">$$ V_{\\mathrm{ar}} = 2 \\cdot B \\cdot S \\cdot H \\cdot \\frac{p-1}{p} \\cdot b $$</div>\n<p>其中 B 为批内序列数、S 为序列长度、H 为隐藏维、p 为 TP 度、b 为字节宽度。NVFP4/FP8 把 b 压到 0.5/1 字节，直接减半通信量——这是量化在并行维度上的隐性收益，不只是算力收益。反过来，若声学生成器按块推进，S 很小（首块只含少量帧），All-Reduce 的固定开销占比上升，TP 度提高后每块的通信延迟可能盖过计算节省。这就是“小块 + 高 TP”在流式 TTS 上的典型陷阱：块越小，通信越像瓶颈。</p>\n<p>具体例子：声学生成器若以 8 卡 TP 运行，每生成一个声学块就要在 8 卡间做两次 All-Reduce；若首块只含数十帧、隐藏维数千，单次 All-Reduce 的数据量落在几十 KB 到百 KB 量级，NVLink 5 域内完成时间极短，但 kernel 启动与同步的固定开销不可忽略。此时把 TP 降到 2–4 卡、把剩余卡用于 DP 承接并发会话，往往比拉高 TP 更划算。判断依据是：通信时间占比 = 通信量 /（通信量 + 计算量），块长越小该比值越高。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-35\">三十五 · All-to-All 与 EP：MoE 声学骨干的隐性代价</h3>\n<p>若声学生成器采用 MoE 结构，EP 会把专家分散到不同 GPU，每个 token 需要经 All-to-All 被路由到所属专家所在卡，算完再 All-to-All 送回。与 All-Reduce 不同，All-to-All 的通信量取决于路由分布：</p>\n<div class=\"formula\">$$ V_{\\mathrm{a2a}} = B \\cdot S \\cdot H \\cdot b \\cdot \\left(1 + \\frac{\\text{top-}k}{E}\\cdot(p-1)\\right) $$</div>\n<p>路由越不均衡（热门专家集中），单卡收发越倾斜，All-to-All 的尾延迟由最忙的那张卡决定。流式场景下这尤其危险：首块生成时 token 数少，路由统计尚未稳定，负载倾斜概率更高。工程手段是容量因子（capacity factor）与路由抖动，但容量因子调大意味着部分 token 被丢弃或排队，直接影响声学表征的连续性，进而影响音画同步。ViDA-MAN 材料未给出声学骨干是否为 MoE，这里只能给出判断规则：若采用 EP，必须把 All-to-All 的尾延迟纳入首包预算，而不是只算平均带宽。</p>\n<p>代价量化上，EP 的显存收益是专家参数按卡分摊，但通信开销随 EP 度上升；在 NVL72 域内，All-to-All 可走 NVLink 全互联，跨域则退化到 InfiniBand，尾延迟显著抬升。因此 EP 的可行域被拓扑钉死：域内 EP 可行，跨域 EP 对首包敏感场景基本不可取。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-36\">三十六 · NIXL 传输：分离式预填/解码的数据面</h3>\n<p>分离式预填/解码把 prefill 与 decode 放到不同 GPU 池，KV cache 需要在池间搬运。NIXL 提供的是点对点、低开销的显存到显存传输抽象，绕过主机内存拷贝，把 KV 块的搬运做成异步 RDMA/NVLink 操作。对 ViDA-MAN 这类多轮对话系统，对话管理器维护的历史与视觉特征缓存同样适合用 NIXL 在会话迁移或池间调度时搬运，而不是重算。</p>\n<p>传输代价的公式很直接：</p>\n<div class=\"formula\">$$ T_{\\mathrm{xfer}} = \\frac{S_{\\mathrm{kv}}}{BW_{\\mathrm{link}}} + T_{\\mathrm{setup}} $$</div>\n<p>KV 块大小随层数、头数、头维与序列长度线性增长；在 NVFP4/FP8 下每元素字节数减半，传输时间同比减半。但 T_setup 是固定项：每次传输的注册与握手开销在小块传输时占比高。因此 NIXL 的工程要点是批量聚合——把多个 KV 块合并为一次传输，压低固定开销占比。流式对话的块很小，聚合窗口的长度直接决定传输效率与首包延迟的权衡：窗口越长，聚合越好，但首块等待越久。</p>\n<p>具体例子：一轮对话结束后历史增量更新，若把新增轮次的 KV 块通过 NIXL 异步搬到持久化池，下一轮请求可直接复用而不重算 prefill。这条路径的收益是多轮场景下的 prefill 节省，代价是传输带宽占用与缓存一致性管理；材料未给出缓存上限与淘汰策略，工程上必须自行设定块粒度与过期规则，否则缓存膨胀会挤占 decode 的显存预算。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-37\">三十七 · 通信何时成为瓶颈：三个判据</h3>\n<p>不要把“通信是瓶颈”当成口号，用三个可测判据定位：其一，单步通信时间与单步计算时间之比跨过阈值。TP 场景下该比值随块长减小而上升，块长低于某个临界值时通信主导；EP 场景下该比值随路由不均衡度上升。其二，尾延迟与平均延迟的偏离。All-to-All 与 All-Reduce 的平均带宽好看不代表首包好看，P99 由最慢链路决定，流式系统必须按尾延迟做预算。其三，域内与域外的断层。NVL72 域内 NVLink 全互联，跨域走 InfiniBand，同一并行策略在两种拓扑下的瓶颈位置完全不同——把域内调优的参数直接搬到跨域部署会失效。</p>\n<table class=\"mini\"><thead><tr><th>并行方式</th><th>通信原语</th><th>随并行度增长的量</th><th>流式场景风险点</th></tr></thead><tbody><tr><td>TP</td><td>All-Reduce</td><td>每层激活量 × (p−1)/p</td><td>小块时固定开销占比高</td></tr><tr><td>EP</td><td>All-to-All</td><td>token 数 × 路由倾斜度</td><td>首块路由未稳定，尾延迟高</td></tr><tr><td>PP</td><td>点对点激活</td><td>stage 边界激活量</td><td>气泡推迟首块产出</td></tr><tr><td>DP</td><td>梯度/参数同步（推理侧仅权重加载）</td><td>副本数</td><td>显存复制，容量规划压力</td></tr></tbody></table>\n<p>把判据落到 ViDA-MAN 的链路上：识别段通常是短序列、计算密集，TP 收益有限，DP 复制更合适；对话管理器承载历史与视觉特征，显存压力大，TP 加 PP 分摊权重、NIXL 搬运缓存；声学生成器是首包关键段，TP 度应保守、块长应适中；声码器切分收益低，DP 承接并发。这个分配不是论文给出的，而是从首包公式与通信判据推出来的工程判断——材料未给出并行拓扑，任何具体卡数与 TP 度都必须由部署方补测确定。</p>\n<p>最后落在机制上：流式声学生成的首块长度是通信与延迟的共同杠杆。块长增大，TP 的 All-Reduce 效率上升、固定开销摊薄，但首块等待变长；块长减小，首包更快，但通信占比上升、尾延迟风险抬头。ViDA-MAN 材料未给出切块阈值，工程上应把块长作为可调参数，用首包 P99 与实时率两个指标联合定标，而不是照搬固定值。音画同步依赖首块与后续块的推流节奏，声码器一旦阻塞，前面所有并行优化都被串联结构吞掉——这也是为什么切分边界必须先于并行度确定。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-38\">三十八 · 切分边界与通信瓶颈：ViDA-MAN 四段流水在并行拓扑上的失效条件</h3>\n\n<p>ViDA-MAN 的推理链路是识别、对话、声学生成、声码器四段串行推进，首包延迟按四段相加。这一结构决定了并行切分不能照搬大模型预填充/解码的常规 TP/EP/PP/DP 组合：声学生成器逐块自回归，声码器按块消费表征，二者之间存在严格的块级依赖，任何跨段并行都必须保持“首块优先”的顺序语义。若把声学生成器做张量并行（TP），每层内的 All-Reduce 会插入到逐块生成的临界路径上；块越小，通信占比越高。设单块计算时间为 $T_{\\mathrm{comp}}$、单块内 TP 组 All-Reduce 耗时为 $T_{\\mathrm{comm}}$，则块级有效加速比为 $S = \\frac{T_{\\mathrm{comp}}}{T_{\\mathrm{comp}}/N + T_{\\mathrm{comm}}}$，当 $T_{\\mathrm{comm}}$ 与 $T_{\\mathrm{comp}}/N$ 同量级时，增加 TP 度 $N$ 不再缩短首块时间，反而抬高首包。这是本方案在并行维度上的第一个边界：首块长度越短、TP 度越高，通信越容易成为瓶颈。</p>\n\n<p>对话管理器与视觉特征缓存适合数据并行（DP）与副本复制，因为多轮会话彼此独立，增量维护的历史与视觉特征按会话隔离。但 DP 副本数受显存约束：每副本需常驻对话历史与当前视频帧特征，材料未给出缓存上限与淘汰策略，副本数增加会线性放大这部分显存占用。专家并行（EP）在本链路中没有天然落点——四段流水不是单一 MoE 主干，把声学生成器拆成专家并引入 All-to-All 只会把块级依赖变成跨卡 token 路由，All-to-All 的尾延迟直接叠加到首块时间上。流水并行（PP）看似匹配四段结构，但 PP 的微批填充会推迟首块进入声码器的时刻，与“首块优先返回”的目标冲突；只有在并发会话足够多、微批能填满流水线时，PP 的吞吐收益才可能抵消首包代价。</p>\n\n<p>通信介质上，NVLink 5 与 NVSwitch 决定单节点内 TP/EP 组的 All-Reduce、All-to-All 带宽，跨节点则落到 NIXL 传输与 NCCL 集合通信。对 ViDA-MAN 这类首包敏感链路，跨节点 TP 是明确的失效条件：一次跨节点 All-Reduce 的时延远高于节点内，而首块声学表征的生成无法用计算掩盖这段时延。工程判断应是把声学生成器与声码器约束在同一 NVLink 域内，把对话管理与视觉特征缓存放到可跨节点扩展的 DP 副本上，用 NIXL 做会话状态与特征的异步搬运，而不是把自回归生成段拆到跨节点。</p>\n\n<table class=\"mini\"><thead><tr><th>切分方式</th><th>对本链路的适用性</th><th>主要代价</th></tr></thead><tbody><tr><td>TP（声学生成器）</td><td>仅节点内、块较大时成立</td><td>块级 All-Reduce 进入首包临界路径</td></tr><tr><td>EP</td><td>无天然落点</td><td>All-to-All 尾延迟叠加首块</td></tr><tr><td>PP（四段）</td><td>高并发下可换吞吐</td><td>微批填充推迟首块进声码器</td></tr><tr><td>DP（会话副本）</td><td>推荐，按会话隔离</td><td>历史与视觉特征显存线性放大</td></tr></tbody></table>\n\n<p>通信成为瓶颈的判据可以落到一个可观测的量：单块内通信时间占块时间的比例。当该比例超过首块预算中声学生成段所占份额时，继续加并行度只会把首包延迟推向声码器阻塞之外的第二个风险点。材料未给出并行拓扑与硬件档位，因此无法给出具体阈值；可核验的机制判断是，ViDA-MAN 的流式首块优先语义与高 TP/EP 度天然互斥，部署时应先固定首块长度与声码器消费节奏，再决定节点内并行度，跨节点只承载会话副本与特征搬运。</p>\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-39\">三十九 · 精度塌陷：从“能出声”到“出怪声”的静默滑落</h3>\n<p>数字人视觉对话的精度塌陷与纯文本推理不同：它不会以报错的形式出现，而是以“还能说话、但说的不是那个意思”的形式出现。ViDA-MAN 的四段流水里，识别段把用户语音转成文本，对话管理器拼上视觉特征生成回复文本，声学生成器逐块产生声学表征，声码器把表征转成波形。精度塌陷可以发生在任意一段，且下游段无法自证上游段已经错了——声码器不会因为声学表征偏离分布而拒绝合成，它照样输出一段听起来流畅的波形。</p>\n<p>机制上，最典型的塌陷路径是声学表征的数值漂移。流式声学生成器按块推进，首块与后续块共享同一份自回归状态；若某一块的表征幅值或量化误差被放大，后续块会在错误的状态上继续生成，误差沿块链累积。这与 KV cache 的数值退化是同一类问题，只是这里的“cache”是声学状态而非注意力键值。诊断上要抓的是块间一致性：对相邻块的表征做能量比与频谱质心比对，若某块相对前块的偏移超过该会话自身的历史分位，就标记为可疑块。公式上可写成块间漂移度量：</p>\n<div class=\"formula\">$$ D_k = \\frac{\\lVert \\hat{a}_k - \\hat{a}_{k-1} \\rVert_2}{\\lVert \\hat{a}_{k-1} \\rVert_2 + \\epsilon} $$</div>\n<p>其中 $\\hat{a}_k$ 是第 $k$ 块声学表征的归一化向量。$D_k$ 本身不是绝对阈值，而是按会话建立基线后看突跳。代价在于：逐块比对需要把表征留在显存里做旁路计算，等于给声学生成器加了一条影子通路，占用少量显存与算力；若把比对放到主机侧，则要付出每块一次的设备到主机拷贝，在流式节奏下这笔带宽开销会直接顶到首包之后的推流间隔上。具体例子：某轮对话中用户语速突然加快，识别段输出的文本切块变密，声学生成器的首块长度被动缩短，声码器在极短块上做归一化时把增益推高，后续块继承了这个偏高的增益，听感上表现为音量突然抬升后缓慢回落——这是精度塌陷而非音量控制问题，监控上应归到块间漂移而非响度指标。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-40\">四十 · OOM 与缓存膨胀：历史与视觉特征的隐性账本</h3>\n<p>ViDA-MAN 的显存压力不来自单次前向，而来自按轮次增量维护的对话历史与视觉特征。增量维护的设计意图是避免每轮对整段历史重算，代价是缓存只增不减的倾向：每轮追加新的文本 token 与当前视频帧特征，旧条目在没有淘汰策略时一直驻留。材料明确未给出缓存上限与淘汰规则，这正是 OOM 风险的结构性来源。多轮会话越长，单会话显存占用越接近线性增长；并发会话数一上来，显存需求就是“会话数 × 单会话缓存”的乘积。</p>\n<p>诊断要区分两种 OOM：分配失败型与碎片型。前者是某次分配直接拿不到连续块，日志里能看到分配器拒绝；后者是总空闲显存够但最大连续块不够，表现为间歇性失败、重试后偶发成功。流式声学生成器的块缓冲与声码器的波形缓冲都是变长分配，最容易制造碎片。工程上应把缓存按“轮次槽位”预分配成固定尺寸的池，视觉特征按帧数上限截断，对话历史按 token 预算截断，截断策略要显式记录被丢弃的轮次编号，否则回滚时无法重建上下文。</p>\n<p>代价上，缓存池化会把峰值显存抬高到“上限 × 并发数”，换来的是分配确定性与更低的碎片失败率；对 SLO 而言这是用容量换稳定。具体例子：一个长会话在第 N 轮后开始间歇性 OOM，而新会话正常，说明问题在单会话缓存膨胀而非全局容量；此时若直接扩并发上限会掩盖问题并放大碎片，正确动作是先给该会话打上“长历史”标签并触发截断，再观察失败率是否回落。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-41\">四十一 · 批抖动与尾延迟：连续批处理在流式音频下的错位</h3>\n<p>批抖动来自批组成的变化率与流式音频的节奏不匹配。ViDA-MAN 的声学生成器按块推进，每块的处理时间短且不均匀；连续批处理会把不同会话的块拼进同一批，一旦某会话的首块到达而其他会话还在等后续块，批的组成就会频繁重排。重排本身要付调度开销，更麻烦的是它把尾延迟放大：一个被反复推迟的块会在队列里等待多个批周期，端到端表现为该会话的推流出现可听见的停顿。</p>\n<p>诊断批抖动要看两个量：批内块的处理时间方差，以及单块从入队到出队的等待分布。前者高说明块长不均，后者长尾说明调度器在饿死某些会话。伪代码思路是给每个会话维护一个“截止块序号”，调度时优先满足截止最近的会话，而不是简单按到达顺序拼批：</p>\n<div class=\"formula\">$$ \\text{priority}_i = \\frac{1}{\\text{deadline}_i - t_{\\text{now}}} + \\lambda \\cdot \\text{starve}_i $$</div>\n<p>其中 $\\text{starve}_i$ 是该会话连续被跳过的批数，$\\lambda$ 控制饥饿补偿强度。代价是优先级计算本身要每批做一次，且高优先级会话会挤占批容量，降低整体吞吐——这是尾延迟与吞吐的直接交换。具体例子：两个并发会话，一个用户说话停顿多、块到达稀疏，另一个连续说话、块到达密集；按到达顺序拼批会让稀疏会话的块长期排在密集会话之后，尾延迟集中在稀疏会话上，而它的用户恰恰因为停顿而对延迟更敏感。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-42\">四十二 · 静默降级：音画不同步与“看起来正常”的故障</h3>\n<p>静默降级是这套系统最危险的一类失败：口型与表情由声码器输出波形驱动，音画同步依赖首块与后续块的推流节奏。材料未给出同步误差指标，这意味着部署侧若不做主动探测，同步漂移会以“数字人还在动、嘴还在动”的表象持续存在。漂移的来源是两条独立的时间线：音频块按声码器节奏推流，视觉驱动按渲染节奏消费；任一侧的缓冲策略变化都会引入固定偏移，而偏移一旦超过人眼可察觉的范围，观感就塌了，但系统指标全是绿的。</p>\n<p>诊断要构造可观测的锚点：在每块波形里嵌入一个与块序号绑定的标记（例如块起始处的特定能量包络），渲染侧消费时回读该标记并与当前渲染帧序号比对，得到端到端同步误差。这个误差要作为一等指标上报，而不是靠人工看视频。代价是标记嵌入会轻微扰动波形，且回读需要渲染侧配合，属于跨模块改造；但不做这一步，静默降级就没有任何自动捕获手段。具体例子：声码器为了抗抖动把输出缓冲从一块加到三块，音频延迟整体后移，视觉驱动仍按原节奏消费，口型开始比声音早——监控上音频指标全部正常，只有同步误差指标会跳变。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-43\">四十三 · 监控、定位与回滚：把四段流水做成可归因的链</h3>\n<p>定位的前提是归因粒度对齐四段流水。首包延迟按 $T_{\\mathrm{first}} = T_{\\mathrm{asr}} + T_{\\mathrm{dialog}} + T_{\\mathrm{acoustic}}^{\\mathrm{first\\ block}} + T_{\\mathrm{vocoder}}^{\\mathrm{first\\ chunk}}$ 拆解，每一段都要有独立的耗时直方图与失败计数，且带上会话标识与轮次序号，否则跨段关联只能靠时间戳猜。监控指标至少覆盖：分段耗时分位、块间漂移 $D_k$ 的突跳率、缓存占用与会话轮次的关系、批等待分布的长尾比例、同步误差绝对值。这些指标要按会话聚合而非全局平均，因为失败往往集中在少数长会话上。</p>\n<p>回滚要按“最小可逆单元”设计。精度塌陷的回滚点是声学生成器的块推进状态：保留最近若干块的输入表征快照，检测到漂移突跳时从快照重放该块而非整轮重来，代价是快照占显存、重放占算力，但避免了整轮对话作废。OOM 的回滚点是缓存截断策略：把长历史会话切到截断档，牺牲上下文保真度换稳定。批抖动的回滚点是调度策略开关：从截止优先切回到达顺序，用尾延迟换吞吐。静默降级的回滚点是缓冲深度：把声码器输出缓冲退回单块并接受抖动，用同步正确性换推流平滑。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>定位手段</th><th>回滚单元</th><th>代价</th></tr></thead><tbody><tr><td>精度塌陷</td><td>块间漂移突跳率</td><td>块级表征比对</td><td>块状态快照重放</td><td>显存与重放算力</td></tr><tr><td>OOM</td><td>分配失败率、碎片率</td><td>按会话缓存占用曲线</td><td>历史截断档</td><td>上下文保真度</td></tr><tr><td>批抖动</td><td>批等待长尾比例</td><td>截止块序号追踪</td><td>调度策略开关</td><td>吞吐</td></tr><tr><td>尾延迟</td><td>单块出队等待分布</td><td>饥饿计数</td><td>饥饿补偿强度</td><td>批容量利用率</td></tr><tr><td>静默降级</td><td>同步误差绝对值</td><td>块标记回读</td><td>声码器缓冲深度</td><td>推流平滑度</td></tr></tbody></table>\n<p>这套监控与回滚的工程判断落在一个具体机制上：把首块与后续块分开治理。首块决定首包延迟与同步起点，必须走最短路径、最严监控、最快回滚；后续块决定持续推流质量，允许更长的缓冲与更宽松的重试。材料未给出任何延迟与失败率数字，因此所有阈值都应在部署侧按会话基线自建，而不是引用外部常数——把流式切块长度当固定值引用、把首包延迟拆解当实测结果、只优化声学生成侧而忽略声码器阻塞，这三种做法都会让诊断链在真实故障面前失效。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-44\">四十四 · 首块阻塞与缓存膨胀：这套流式链路的失效边界</h3>\n<p>ViDA-MAN 的首包时间由四段串联相加，任一环节阻塞都会直接抬高端到端首包，因此诊断的第一原则是<strong>按段归因而非看总延迟</strong>。声学生成器与声码器分离推进意味着二者可以并行，但首块必须串行：声学首块未产出，声码器无输入可合成，数字人的口型与表情也就无从驱动。机制上最直接的风险点是首块长度——回复文本按语义切块，首块越长，声学侧自回归推进的步数越多，首包被拉长；首块过短则语义不完整，后续块拼接处易出现韵律断裂。可用的诊断式是分段打点：对每轮请求记录 $T_{\\mathrm{asr}}$、$T_{\\mathrm{dialog}}$、$T_{\\mathrm{acoustic}}^{\\mathrm{first\\ block}}$、$T_{\\mathrm{vocoder}}^{\\mathrm{first\\ chunk}}$ 四个时间戳，任一环节的 P99 抬升即定位到该段，而不是笼统归因于“TTS 慢”。代价上，分段打点本身引入同步开销，需在采样率与精度间取舍：全量打点会拖慢高频短请求，按会话抽样则可能漏掉长尾。</p>\n<p>第二类失效是显存侧的<strong>缓存膨胀与批抖动</strong>。对话历史与视觉特征按轮次增量维护，避免整段重算，但材料未给出缓存上限与淘汰策略——多轮会话越长，历史与视觉特征驻留越多，并发上升时显存压力非线性增长。批调度需同时兼顾实时率与并发：批越大，单批内首包等待越久，尾延迟被拉长；批越小，声码器与声学生成器的流水填充不足，吞吐下降。工程判断是给缓存设硬上限并按轮次滑窗淘汰，同时把首包请求与后续补帧请求分池调度，避免长会话挤占新会话的首包窗口。显存代价体现在视觉特征缓存上：每轮视频帧特征若不做压缩或复用，驻留量随轮次线性累积。</p>\n<p>第三类是<strong>静默降级</strong>：声码器阻塞或首块生成超时后，系统若继续推流后续块而不报警，客户端表现为音画不同步或口型滞后，但服务端指标仍显示“成功”。这类失效不会体现在失败率上，只能靠音画同步误差与首包超时率两个指标捕获。回滚策略应绑定切块阈值与缓存上限两个可调参数：一旦首包 P99 越界，先回退到更短的首块长度与更保守的缓存上限，再排查声码器侧阻塞。下表给出失效模式与对应观测点。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>机制根因</th><th>观测点</th><th>系统代价</th></tr></thead><tbody><tr><td>首包拉长</td><td>首块过长、声学自回归步数多</td><td>声学首块耗时 P99</td><td>首包延迟上升</td></tr><tr><td>音画不同步</td><td>声码器阻塞、后续块推流节奏错位</td><td>同步误差、首包超时率</td><td>静默降级、体验损失</td></tr><tr><td>显存膨胀</td><td>历史与视觉特征无上限累积</td><td>缓存驻留量、OOM 率</td><td>并发上限下降</td></tr><tr><td>批抖动</td><td>批大小与实时率冲突</td><td>尾延迟、批填充率</td><td>吞吐与尾延迟权衡</td></tr></tbody></table>\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-45\">四十五 · 口径先行：这张卡能测什么、不能测什么</h3>\n<p>ViDA-MAN 的论文卡只提供系统级机制描述，没有硬件档位、量化方案、并行拓扑，也没有任何延迟、实时率或吞吐数字。这意味着任何“ViDA-MAN 在 B200 上达到多少毫秒首包”的说法都是编造。本部分的任务不是给出数字，而是建立一套<strong>可复用的口径框架</strong>：把论文卡里可核验的机制映射到 Blackwell 推理基准的标准维度上，明确哪些量可以从机制推出、哪些量必须补测、哪些跨系统对比在方法上不成立。</p>\n<p>基准口径的第一原则是<strong>指标必须绑定负载形态</strong>。ViDA-MAN 的负载是多轮语音请求，每轮含用户语音流与当前视频帧，回复文本按语义切块送入声学生成器。这决定了它的核心指标不是离线吞吐，而是首包延迟与实时率（RTF）。论文卡给出的唯一可核验公式是端到端首包时间的四段加和：</p>\n<div class=\"formula\">$$ T_{\\mathrm{first}} = T_{\\mathrm{asr}} + T_{\\mathrm{dialog}} + T_{\\mathrm{acoustic}}^{\\mathrm{first\\ block}} + T_{\\mathrm{vocoder}}^{\\mathrm{first\\ chunk}} $$</div>\n<p>这个公式本身就是口径声明：首包延迟是<strong>串联和</strong>，不是任何单段的局部最优。工程上常见的误读是把声学生成侧的首块耗时当作系统首包时间，忽略声码器首块合成与识别、对话两段的固定开销。在 Blackwell 档位上做容量规划时，四段必须分别测量、分别归因，否则优化方向会错配。</p>\n<p>具体例子：假设某部署把声学生成首块压到极短，但声码器首块需要等待完整的声学表征窗口才能启动，则端到端首包被声码器段支配。此时继续压缩声学生成首块长度对 <span class=\"formula\">$$T_{\\mathrm{first}}$$</span> 的边际贡献趋近于零，正确的动作是改声码器的分块策略或让两段流水重叠。这个判断不依赖任何实测数字，只依赖公式的串联结构。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-46\">四十六 · 硬件档位与 batch：机制上能推的代价边界</h3>\n<p>论文卡明确未说明是否使用 B200/B300/GB200 NVL72，也未说明声学模型与声码器的切分方式。因此硬件档位在本卡中只能作为<strong>待补全的坐标轴</strong>，而不是结论。但机制层面可以给出代价边界的定性判断，供补测时设计实验矩阵。</p>\n<p>数字人视觉对话的显存占用由三部分构成：对话历史缓存、视觉特征缓存、声学模型与声码器的权重及激活。论文卡指出历史与视觉特征按轮次增量维护，避免整段重算——这直接降低了每轮的重算算力，但把代价转移到了<strong>常驻显存</strong>上。增量缓存的上限未给出，意味着显存随会话轮次单调增长的斜率不可控。在 Blackwell 的容量规划里，这对应一个必须显式设定的淘汰策略参数，否则并发会话数无法给出上界。</p>\n<p>batch 维度上，ViDA-MAN 的批调度需兼顾实时率与并发。流式声学生成的逐块推进天然是<strong>变长序列</strong>：不同会话的首块到达时间不同，后续块的推进节奏也不同。连续批处理（continuous batching）在这里的收益来自把多个会话的声学块拼进同一批 MMA，但代价是首包延迟受同批最长会话的阻塞影响。这是一个明确的吞吐—延迟权衡：</p>\n<div class=\"formula\">$$ \\mathrm{Goodput} = \\frac{N_{\\mathrm{sess}} \\cdot L_{\\mathrm{utt}}}{T_{\\mathrm{wall}}}, \\quad \\text{s.t.}\\ \\max_i T_{\\mathrm{first}}^{(i)} \\le \\mathrm{SLO} $$</div>\n<p>约束项是关键：并发数 <span class=\"formula\">$$N_{\\mathrm{sess}}$$</span> 不能只看吞吐最大化，必须满足最严会话的首包 SLO。在 SM100 上，tcgen05 与 2-SM MMA 的批处理效率随批大小提升，但首包 SLO 会把有效批大小压在一个由最慢会话决定的水平上。具体例子：若某会话因视觉特征较长导致对话段耗时偏高，把它与短会话拼批会让整批的首包被它拉长，短会话的 SLO 被牺牲。正确做法是按预估首包耗时分层组批，而不是按到达顺序贪心拼批。</p>\n<p>功耗维度上，论文卡无数据。机制上可说的是：流式两段推进让声学生成与声码器可以流水重叠，重叠区的功耗是两段之和而非峰值取大，这在 NVL72 机柜级功耗预算里是需要单独建模的项，不能沿用离线推理的峰值功耗假设。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-47\">四十七 · 指标怎么读：TTFT/TPOT 在语音链路上的映射</h3>\n<p>LLM 推理的标准指标是 TTFT（首 token 时间）与 TPOT（每 token 时间）。ViDA-MAN 的链路不能直接套用这两个词，但可以做结构映射，映射的准确性决定了跨系统对比是否成立。</p>\n<ul>\n<li><strong>TTFT 映射为首包延迟</strong>：即上面的 <span class=\"formula\">$$T_{\\mathrm{first}}$$</span>，包含识别、对话、首块声学、首块声码器四段。与 LLM 的 TTFT 相比，它多了前置的 ASR 段和后置的声码器段，因此数值上不可与纯文本 LLM 的 TTFT 直接比较。</li>\n<li><strong>TPOT 映射为块间推进间隔</strong>：流式声学生成逐块产出表征，块与块之间的时间间隔决定后续语音是否连续。这个量不是“每 token 时间”，而是“每语义块时间”，块长度由语义切块决定，论文卡未给出阈值。</li>\n<li><strong>吞吐映射为会话完成率</strong>：单位时间内完成的对话轮数，受实时率约束。RTF 小于 1 是流式推流不中断的必要条件，但论文卡未给出 RTF 数值。</li>\n</ul>\n<p>读数的核心陷阱是<strong>把块级指标当成端到端指标</strong>。块间推进间隔短，不代表端到端首包短；首块声学快，不代表声码器不阻塞。具体例子：某部署报告“声学生成首块耗时很低”，这个数只能填入公式的第三项，不能作为系统首包延迟对外宣称。对外口径必须声明测量点是哪一段、是否含 ASR 与声码器、是否含网络推流。</p>\n<p>显存指标同样需要口径声明：是峰值显存还是稳态显存，是否含增量缓存的历史累积。论文卡指出缓存按轮次增量维护，因此稳态显存在长会话下会高于首轮，只报首轮显存会系统性低估容量需求。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-48\">四十八 · 哪些提升不可比：跨系统对比的方法边界</h3>\n<p>ViDA-MAN 没有给出对比基线，也没有消融实验。这意味着任何“比某系统快多少”的表述都缺乏锚点。更严格地说，即使未来补测出数字，跨系统对比仍需满足三个条件才成立，缺一不可。</p>\n<ul>\n<li><strong>负载同构</strong>：对比双方的首块长度、语义切块策略、视觉特征维度必须一致。ViDA-MAN 的切块阈值未给出，若一方用更短的首块换取更低首包，这是策略差异而非系统能力差异，不能直接比较。</li>\n<li><strong>测量点同构</strong>：是否含 ASR、是否含声码器、是否含推流网络。只测声学生成段的数字与测端到端四段的数字不在同一坐标系。</li>\n<li><strong>硬件与量化同构</strong>：论文卡未说明 NVFP4/FP8 的使用情况。在 Blackwell 上，量化方案对声学模型权重带宽与声码器激活的影响是数量级的，未声明量化的对比没有意义。</li>\n</ul>\n<p>不可比的典型场景是把 ViDA-MAN 的机制优势（首块优先、增量缓存）当作性能优势引用。机制优势是<strong>结构性</strong>的：它降低了重算算力、把首包从“整段生成后合成”改为“首块即合成”。但结构优势能否转化为端到端延迟优势，取决于声码器首块是否真的与声学生成重叠、取决于 ASR 段是否成为新瓶颈。论文卡没有数据证明转化成立，因此只能定性表述为“机制上为首包优先提供了路径”。</p>\n<p>另一个不可比点是音画同步。论文卡指出口型与表情由声码器输出波形驱动，同步依赖首块与后续块的推流节奏，但未给出同步误差指标。把音频首包延迟当作音画同步质量的代理指标是错的：音频先到而口型驱动滞后，同步误差可能反而变大。同步误差需要独立的测量口径，不能从首包延迟推出。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-49\">四十九 · 补测设计：把这张卡变成可核验的基准</h3>\n<p>既然论文卡缺硬件、量化、并行与监控，补测的设计必须先把坐标轴钉死，再填数字。以下是一个最小可核验的补测矩阵思路，每一项都对应论文卡里明确缺失的字段。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>论文卡状态</th><th>补测口径要求</th></tr></thead><tbody><tr><td>硬件档位</td><td>未给出</td><td>声明 B200/B300/GB200 NVL72 具体型号与卡数</td></tr><tr><td>量化方案</td><td>未给出</td><td>声明声学模型与声码器各自的精度（NVFP4/FP8/FP16）</td></tr><tr><td>并行拓扑</td><td>未给出</td><td>声明两段是否同卡、是否跨 NVLink 域切分</td></tr><tr><td>首包延迟</td><td>未给出</td><td>按四段分别计时，报告串联和与各段占比</td></tr><tr><td>实时率</td><td>未给出</td><td>声明块长度与推流节奏，报告 RTF 分布而非均值</td></tr><tr><td>显存</td><td>未给出</td><td>报告首轮稳态与长会话稳态两组，含增量缓存</td></tr><tr><td>并发</td><td>未给出</td><td>报告满足首包 SLO 的最大会话数及对应批策略</td></tr></tbody></table>\n<p>补测的执行顺序有讲究：先固定切块策略再测延迟，否则首块长度变化会污染所有延迟读数。论文卡明确首块长度直接决定首包延迟，因此切块阈值是<strong>受控变量</strong>而非自由变量。具体例子：若补测时一边调首块长度一边报首包延迟，得到的曲线无法归因于系统能力，只能归因于策略扫描。</p>\n<p>监控指标方面，论文卡未说明首包延迟、实时率与失败率的采集方式。机制上最直接的风险点是首块过长与声码器阻塞，因此监控必须至少覆盖：四段各自的耗时分布、声码器首块等待时间、增量缓存的显存增长斜率。这三项缺任何一项，失败模式都无法定位到具体段。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-50\">五十 · 落到工程判断：口径即容量规划的前置条件</h3>\n<p>对 Blackwell 部署而言，ViDA-MAN 这张卡的价值不在于给出性能结论，而在于它把数字人视觉对话的推理链路拆成了<strong>可分别计时的四段</strong>，并明确了首包优先与增量缓存两个机制点。这两个机制点直接对应容量规划里的两个参数：首包 SLO 决定有效批大小上限，增量缓存上限决定并发会话数的显存上界。</p>\n<p>工程判断可以写得很具体：在没有补测数据之前，不应把 ViDA-MAN 纳入任何跨系统的吞吐对比表；可以把它作为<strong>机制参照</strong>，用于设计流式 TTS 与音画同步的测量口径。补测时优先测声码器首块的等待时间，因为它是串联公式里最容易被忽略、又最容易成为实际瓶颈的一段。若声码器首块与声学生成首块不能重叠，则四段加和退化为严格串行，首包延迟的优化空间被锁死在最慢段上——这个判断不需要任何数字，只需要流水结构。</p>\n<p>最后一条口径纪律：任何对外报告的首包延迟必须标注测量点与是否含推流。ViDA-MAN 的首包定义是“数字人开始说话”的时刻，这个时刻由声码器输出波形驱动口型，因此测量点应落在波形推流而非声学表征产出。把测量点前移到声学生成段会让数字好看，但口径失真，后续的容量规划会建立在错误锚点上。</p>\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-51\">五十一 · 迁移到非流式模型：首块优先的前提会失效</h3>\n<p>ViDA-MAN 的推理骨架之所以成立，靠的是一个隐含契约：声学生成器能在收到第一段语义块后立刻吐出可用的首块表征，声码器不必等整句结束就能合成波形。这个契约在自回归逐帧声学模型上天然满足，因为逐帧生成本身就是增量的。一旦把同一套四段流水搬到非自回归或整句扩散式声学模型上，首块优先就退化成“整句优先”——扩散采样需要固定步数迭代整段隐变量，首块与末块在同一轮去噪里同时成熟，<div class=\"formula\">$$ T_{\\mathrm{first}} = T_{\\mathrm{asr}} + T_{\\mathrm{dialog}} + T_{\\mathrm{diffuse}}^{\\mathrm{full\\ utterance}} + T_{\\mathrm{vocoder}}^{\\mathrm{first\\ chunk}} $$</div>公式里第二项之后的声学项不再是“首块”而是“整句”，首包延迟被整句生成时间钉死。迁移判断很直接：只有当目标声学模型具备因果、可截断的增量生成能力时，才值得保留首块优先的调度结构；否则应把优化预算从“切块节奏”转到“整句生成并行度”，例如把扩散步数摊到多卡或改用少步采样，而不是硬套流式切块。</p>\n<p>工程代价体现在批调度上。流式声学模型可以在一个 batch 里混入处于不同块位置的请求，连续批处理按块推进；整句扩散模型则要求同一 batch 内所有请求等长或补齐到最长句，padding 直接吃掉吞吐。对数字人场景，这意味着并发会话数上升时，尾部长句会把整批的首包延迟一起拖高，SLO 从“首包 P99”退化为“最长句生成时间”。这是迁移时最先要重估的容量口径。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-52\">五十二 · 视觉特征缓存：增量维护的边界在特征维度与轮次深度</h3>\n<p>对话历史与视觉特征按轮次增量维护，是本方案里最容易被误迁移的部分。增量缓存的收益来自“不重算旧轮”，但代价是缓存随轮次线性增长。设第 <span>t</span> 轮缓存的视觉 token 数为 <span>V</span>、历史文本 token 为 <span>H</span>，则第 <span>t</span> 轮的显存占用近似为 <div class=\"formula\">$$ M_t \\approx M_{\\mathrm{model}} + \\sum_{i=1}^{t} \\alpha\\,(V_i + H_i) $$</div>其中 <span>α</span> 是每 token 的 KV 字节数。数字人场景里视觉特征是逐帧提取的，<span>V_i</span> 往往远大于 <span>H_i</span>，于是缓存膨胀的主项是视觉而非文本。迁到视频帧率更高、分辨率更大的领域（如远程问诊、工业巡检的数字人），<span>V_i</span> 会成倍上升，增量缓存从“省算力”变成“吃显存”。判断标准是：当视觉 token 的 KV 占用超过单卡可用显存的一个固定比例时，增量缓存必须配淘汰策略——按轮次滑窗、按语义重要性保留关键帧特征、或把旧轮视觉特征降维后再缓存。材料未给出缓存上限与淘汰规则，迁移时这一步不能省，否则长会话会在第若干轮后触发 OOM，而失败点出现在对话中途，用户感知为数字人突然卡死。</p>\n<p>另一个边界是跨模态对齐。ViDA-MAN 的视觉特征与当前轮语音绑定，增量缓存假设“旧视觉特征仍然语义有效”。迁到视觉场景快速变化的领域（驾驶舱、直播带货），旧帧特征很快失效，继续缓存不仅占显存还污染对话理解。此时正确做法不是加大缓存，而是缩短视觉特征的有效窗口，把增量维护从“全历史”改为“滑动窗口 + 摘要”。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-53\">五十三 · 声码器与音画同步：迁移到高帧率驱动时节奏会错位</h3>\n<p>数字人口型与表情由声码器输出波形驱动，音画同步依赖首块与后续块的推流节奏。这里的机制耦合是：声码器每产出一个 chunk 的波形，驱动层就取对应时长的口型参数。迁移到不同驱动模型时，最容易被忽略的是驱动侧的时间粒度。若目标数字人驱动要求每 20ms 更新一次口型，而声码器 chunk 是 200ms，驱动层要么插值要么等待，插值会引入口型与音频的相位差，等待则直接抬高首包后的连续推流延迟。判断依据是驱动粒度与声码器 chunk 长度的整除关系：不整除时，同步误差会随 chunk 累积，长回复里口型逐渐漂移。</p>\n<p>系统代价在这里表现为“首包之后”的稳定性而非首包本身。首包延迟只由第一块决定，但连续推流的实时率由后续块与驱动的消费速率共同决定。若驱动层消费慢于声码器产出，缓冲区膨胀，端到端延迟随回复长度增长；若驱动层快于产出，出现音频空洞。迁移到高帧率、低延迟驱动的领域（如虚拟主播实时互动），必须把声码器 chunk 长度压到与驱动粒度同量级，代价是声码器调用次数上升、单次利用率下降，吞吐换延迟。材料未给出同步误差指标，迁移时应在驱动层加时间戳对齐，而不是假设 chunk 边界天然对齐。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-54\">五十四 · 规模上限：四段流水串联，最慢段决定并发天花板</h3>\n<p>四段流水是串联结构，端到端首包延迟是四段之和，因此系统并发上限不由总算力决定，而由最慢段的排队行为决定。设各段服务时间为 <span>s_i</span>、到达率为 <span>λ</span>，串联系统的稳定条件是 <span>λ · max(s_i) < 1</span>，即吞吐天花板等于最慢段的服务率。数字人场景里，声学首块生成与声码器首块合成通常是慢段，识别与对话理解相对轻。迁到更大模型或更长回复的领域，慢段会转移：对话管理器若换成大参数多模态模型，<span>s_dialog</span> 上升，瓶颈从声学侧移到理解侧，此时继续优化声学切块对端到端首包帮助有限。</p>\n<p>规模上限还受批调度策略约束。流式声学模型可以细粒度混批，但声码器往往按 chunk 调用，批内 chunk 长度不一时利用率下降。并发上升时，声码器成为串行化点，GPU 利用率与并发数脱钩。工程判断是：迁移前先测四段各自的服务时间分布，找出 <span>max(s_i)</span>，把优化预算集中在该段；若最慢段是声码器，优先考虑把声码器与声学生成放在同一批调度里做流水重叠，而不是单纯加卡。材料未给出各段参数量与并行切分，迁移时这一步必须补测，否则容量规划会按总算力估算，实际并发被最慢段卡住。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-55\">五十五 · 不适用的场景与判断清单</h3>\n<p>这套方案不适用于三类目标。第一类是无实时语音输出的视觉对话——若产品只返回文本，声学与声码器两段不存在，首块优先的整套调度结构失去意义，迁移时应直接砍掉后两段，把预算给对话理解与视觉编码。第二类是离线批量生成数字人视频——首包延迟不再是约束，吞吐由整段生成决定，流式切块反而增加调度开销，应改为整段批处理。第三类是强音画同步且驱动模型不可控的封闭系统——声码器 chunk 长度无法与驱动粒度对齐时，首块优先带来的低首包会被同步误差抵消，用户感知的是口型漂移而非快。</p>\n<p>迁移判断可以落成一张检查表：目标声学模型是否因果可截断；视觉特征的有效窗口是否短于会话长度；驱动粒度是否整除声码器 chunk；四段中哪段是 <span>max(s_i)</span>；缓存是否有淘汰策略。五项里任一不满足，就不应原样搬运四段流水，而应重排瓶颈段。规模上限的判断则更简单：串联系统的并发天花板等于最慢段服务率的倒数，任何按总算力做的容量估算都会高估。材料只给出机制描述、没有硬件与量化锚点，因此迁移到 Blackwell 档位时，这套方案能提供的是调度结构参照，不是容量数字；真正的部署判断必须来自对四段服务时间的实测，而不是对论文卡机制的类比。</p>\n\n<h3 id=\"paper-vida-man-visual-dialog-with-digital-2021-sec-56\">五十六 · 迁移的代价不在算子，在流式契约的重新谈判</h3>\n<p>把这套四段流水搬到别的模型上，最先崩掉的不是声学模型本身，而是首块长度与后续块推进节奏之间的隐含契约。ViDA-MAN 的机制是回复文本按语义切块送入声学生成器，首块优先返回、声码器立即合成推流，后续块边生成边补齐；这套节奏成立的前提是声学模型能在极短上下文内产出可懂的首块表征，且声码器对首块不依赖未来帧。换到一个上下文依赖更强的自回归声学模型（例如需要更长历史韵律建模），首块就必须携带更多前文，首包延迟随首块长度线性抬升：$$ T_{\\mathrm{first}} = T_{\\mathrm{asr}} + T_{\\mathrm{dialog}} + T_{\\mathrm{acoustic}}^{\\mathrm{first\\ block}} + T_{\\mathrm{vocoder}}^{\\mathrm{first\\ chunk}} $$ 四项里前三项随模型规模与上下文增长，只有最后一项能靠声码器切块并行压缩。迁到非流式声码器（如需要整句归一化的扩散声码器）时，首块无法独立合成，整条流式契约失效，只能退回整句合成再推流，首包时间被整句生成时间支配。工程判断：迁移前先测声码器对首块的最小可合成窗口，窗口大于语义块长度就直接放弃流式方案。</p>\n<p>领域迁移的第二类代价在缓存语义。对话历史与视觉特征按轮次增量维护，避免整段重算，这在数字人场景成立是因为视觉特征来自当前视频帧、轮次间变化有限；迁到视频理解或长文档问答时，视觉/文本上下文每轮大幅变化，增量缓存的命中率下降，缓存膨胀直接吃掉显存预算。以 KV 缓存占用估算：单会话显存 ≈ 层数 × 头数 × 头维 × 序列长度 × 每元素字节 × 2（K/V），序列长度包含对话历史与视觉 token；当视觉 token 占比升高，序列长度增长快于回复长度，批调度可容纳的并发会话数被压缩。此时需要按轮次做缓存淘汰或对视觉特征做池化压缩，但材料未给出淘汰策略，迁移方必须自行设定上限，否则并发上限不可控。系统代价体现在吞吐与显存两侧：缓存不淘汰则并发下降，淘汰过激则每轮重算视觉编码，首包延迟回升。</p>\n<p>规模上限由三处共同决定，且都不是靠堆卡能线性解决的。其一是首包延迟的固定开销：识别、对话、首块声学、首块声码器四段串联，任一段阻塞都直接抬高首包时间，声码器阻塞是最容易被低估的一项——只优化声学生成侧会把端到端首包时间算少。其二是实时率约束下的批调度：声学生成器逐块产出，块间存在依赖，连续批处理只能在同一块的多个会话间拼批，块边界成为天然的同步点，批大小受最慢会话的首块生成时间限制。其三是音画同步：口型与表情由声码器输出波形驱动，首块与后续块的推流节奏决定同步误差，材料未给出同步误差指标，迁移到高帧率渲染或低延迟网络时，推流抖动会直接暴露为口型错位。判断：这套方案适合首块短、声码器可切块、视觉上下文稳定的场景；不适合整句依赖强的声学模型、非流式声码器、视觉 token 每轮剧变的领域。迁到 Blackwell 档位时，量化与并行拓扑材料未给出，容量规划必须另行补测，不能把机制描述当作吞吐锚点。</p>\n<table class=\"mini\"><thead><tr><th>迁移维度</th><th>成立条件</th><th>失效后的系统代价</th></tr></thead><tbody><tr><td>声学模型上下文</td><td>首块可在短上下文内独立生成</td><td>首块变长，首包延迟线性抬升</td></tr><tr><td>声码器流式性</td><td>首块可独立合成</td><td>退回整句合成，首包被整句支配</td></tr><tr><td>视觉/历史缓存</td><td>轮次间特征变化有限</td><td>缓存膨胀压缩并发，显存吃紧</td></tr><tr><td>批调度同步点</td><td>块边界可拼批</td><td>批大小受最慢首块限制，吞吐下降</td></tr></tbody></table>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">ViDA-MAN: Visual Dialog </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">with Digital Hu…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2021 · arXiv preprint</text></svg><figcaption><b>家谱</b> · ViDA-MAN: Visual Dialog… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>材料未给出对比基线</td></tr><tr><td>主要结果</td><td>材料未给出可核验的延迟、实时率或吞吐数字；只能确认系统按识别、对话、声学生…</td></tr><tr><td>消融</td><td>材料未给出消融实验；无法核验流式切块长度、首块策略与缓存增量更新各自对首包…</td></tr><tr><td>局限</td><td>材料未给出失败模式与监控指标；按机制推断，首块过长、声码器阻塞与历史缓存膨…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-vida-man-visual-dialog-with-digital-2021 · 共 9 个片段</p>\n";break;}}})();
